NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Exodus'

CHAPTERS = {
    1: {
        1: 'Und dies sind die Namen der Söhne Israels, die nach Ägypten gekommen sind. Mit Jakob sind sie gekommen, jeder mit seiner Familie:',
        2: 'Ruben, Simeon,Levi, Juda,',
        3: 'Issakar, Zabulon, Benjamin,',
        4: 'Dan, Naphtali, Gad und Asser.',
        5: 'Aller Seelen der aus Jakob Entsprungenen waren es siebzig; Joseph aber war schon in Ägypten gewesen.',
        6: 'Da starben Joseph und alle seine Brüder, jenes ganze Geschlecht.',
        7: 'Die Israeliten aber waren fruchtbar geworden; sie wurden überreich, wuchsen und erstarkten mehr und mehr, und das Land ward ihrer voll.',
        8: 'Da trat in Ägypten ein neuer König auf, der von Joseph nichts wußte.',
        9: 'Er sprach zu seinem Volk: "Das Volk der Söhne Israels wird uns zu viel und zu stark.',
        10: 'Wohlan! Überlisten wir es, daß es nicht weiter wachse! Sonst könnte es sich, falls ein Krieg wider uns ausbreche, zu unseren Gegnern schlagen und gegen uns kämpfen und dann aus dem Lande ziehen."',
        11: 'so setzten sie Fronvögte darüber, um mit Fronarbeiten es zu drücken. Und so baute es Pitom und Ramses zu Vorratsstädten für Pharao aus.',
        12: 'Aber je mehr sie es drückten, desto mehr nahm es zu und breitete sich aus. Da graute jenen vor den Israeliten.',
        13: 'Und so machten die Ägypter die Israeliten gewaltsam zu Sklaven',
        14: 'und verbitterten ihnen das Leben mit harter Fron in Lehm und Ziegeln und allerlei Fron auf dem Felde. All ihr Frondienst, den man ihnen aufgelegt hatte, geschah mit Plackerei.',
        15: 'Dann sprach der König von Ägypten zu den Hebammen der Hebräerinnen; die eine hieß Siphra, die andere Pua.',
        16: 'Er sagte: "Entbindet ihr die Hebräerinnen, dann beseht ihr die Teile. Ist es ein Knabe, dann tötet ihr ihn. Ist es ein Mädchen, mag es leben."',
        17: 'Die Hebammen aber fürchteten Gott, und so taten sie nicht, was ihnen der König von Ägypten befohlen, sondern ließen die Knaben am Leben.',
        18: 'Da schrie der König von Ägypten die Hebammen an und sprach zu ihnen: "Warum habt ihr dies getan? Ihr ließet die Knaben am Leben."',
        19: 'Da sprachen die Hebammen zu Pharao: "Die Hebräerinnen sind nicht wie die ägyptischen Weiber; sie sind wie Tiere. Bevor die Hebamme zu ihnen kommt, haben sie geboren."',
        20: 'Und Gott ließ es den Hebammen gut ergehen. Das Volk aber wuchs und wurde sehr stark.',
        21: 'Weil aber die Hebammen Gott gefürchtet hatten, verlieh er ihnen Vermögen.',
        22: 'Pharao aber befahl seinem ganzen Volke: "Ihr sollt alle Knaben, die geboren werden, in den Nil werfen. Die Mädchen aber sollt ihr am Leben lassen."',
    },
    2: {
        1: 'Da ging ein Mann aus Levis Haus hin und heiratete eine Tochter Levis.',
        2: 'Und das Weib ward guter Hoffnung und gebar einen Sohn. Als sie sah, daß er kräftig ward, verbarg sie ihn drei Monate.',
        3: 'Länger aber konnte sie ihn nicht verborgen halten. So nahm sie für ihn ein Papyruskästchen, dichtete es mit Asphalt und Pech, legte den Knaben darein und setzte es in das Schilf am Nilufer.',
        4: 'Seine Schwester aber stellte sich von ferne auf, zu sehen, was mit ihm geschähe.',
        5: 'Da stieg Pharaos Tochter herab, im Nil zu baden, währenddessen sich ihre Dienerinnen am Nilufer ergingen. Da sah sie das Kästchen mitten im Schilfe. Und sie schickte ihre Magd und ließ es holen.',
        6: 'Sie öffnete es und sah es, das Kind. Ein weinender Knabe war es. Und er dauerte sie. Sie sprach: "Dies ist einer von den Knaben der Hebräer."',
        7: 'Da sprach seine Schwester zu der Tochter Pharaos: "Soll ich gehen? Dann hole ich dir ein stillendes Weib von den Hebräerinnen, daß sie dir den Knaben stille?"',
        8: 'Und Pharaos Tochter sprach zu ihr: "Geh!" Da ging das Mädchen und holte des Knaben Mutter.',
        9: 'Und Pharaos Tochter sprach zu ihr: "Nimm diesen Knaben und stille ihn mir! Ich gebe dir einen Lohn dafür." Da nahm das Weib den Knaben und stillte ihn.',
        10: 'Der Knabe wuchs heran; da brachte sie ihn der Tochter Pharaos, und er galt ihr als Sohn. Sie nannte ihn Moses; sie sagte nämlich: "Ich habe ihn aus dem Wasser gezogen."',
        11: 'In jener Zeit, als Moses erwachsen war, ging er zu seinen Brüdern hinaus und sah sich ihre Fronarbeiten an. Da sah er, wie ein ägyptischer Mann einen hebräischen Mann, einen seiner Brüder, niederschlug.',
        12: 'Er wandte sich nun hierhin und dorthin, und als er sah, daß kein Mensch da war, erschlug er den Ägypter. Dann verscharrte er ihn im Sand.',
        13: 'Am andern Tage ging er wieder aus. Da rauften sich zwei Hebräer. Er sprach zu dem Schuldigen: "Warum schlägst du deinen Genossen?"',
        14: 'Da sprach er: "Wer hat dich zum Obmann und Richter über uns gesetzt? Denkst du daran, mich totzuschlagen, wie du den Ägypter totgeschlagen hast?" Da erschrak Moses und dachte: "So ist die Sache ruchbar geworden."',
        15: 'Auch Pharao erfuhr davon und trachtete, Moses umzubringen. Da floh Moses vor Pharao, kam in das Land Midian und setzte sich an den Brunnen.',
        16: 'Der Priester Midians aber hatte sieben Töchter. Diese kamen und wollten Wasser schöpfen und die Tränkrinnen füllen, um ihres Vaters Schafe zu tränken.',
        17: 'Da kamen die Hirten und vertrieben sie. Moses aber stand auf, half ihnen und tränkte ihre Schafe.',
        18: 'Als sie zu ihrem Vater Raguel kamen, sprach er: "Warum kommt ihr heute so bald?"',
        19: 'Sie sprachen: "Ein ägyptischer Mann hat uns gegen die Hirten geholfen. Er hat fleißig für uns geschöpft. Dann tränkte er die Schafe."',
        20: 'Da sprach er zu seinen Töchtern: "Wo ist er? Warum habt ihr den Mann dort gelassen? Ladet ihn zum Mahle ein!"',
        21: 'Und Moses willigte ein, bei dem Manne zu bleiben. Und er gab seine Tochter Sippora dem Moses.',
        22: 'Sie gebar einen Sohn, und er hieß ihn Gersom; denn er sprach: "Gast bin ich geworden in fremdem Lande."',
        23: 'Nach vielen Tagen starb der König von Ägypten. Die Israeliten aber seufzten unter der Fron und schrien auf. Und ihr Hilferuf stieg zu Gott von der Fron empor.',
        24: 'Und Gott hörte ihr Gestöhn. Gott aber gedachte seines Bundes mit Abraham, Isaak und Jakob.',
        25: 'Und Gott sah die Söhne Israels. Und Gott nahm sich ihrer an.',
    },
    3: {
        1: 'Moses aber hütete die Schafe seines Schwiegervaters Jetro, des Priesters von Midian. Da trieb er einmal die Schafe nach der Wüste und kam zu dem Gottesberg, an den Horeb.',
        2: 'Da erschien ihm der Engel des Herrn mitten im Feuer aus dem Dornbusch heraus. Er sah hin: Der Dombusch brannte in Feuer; aber der Dornbusch ward nicht verzehrt.',
        3: 'Da sprach Moses: "Ich will doch hingehen, diese großartige Erscheinung zu betrachten, warum der Dornbusch nicht verbrennt."',
        4: 'Als der Herr sah, daß er herüberkam, um aufzuschauen, da rief ihn Gott aus dem Dornbusche an und sprach: "Moses! Moses!" Er sprach: "Hier bin ich."',
        5: 'Er sprach: "Komm nicht näher! Streif deine Schuhe von den Füßen! Denn der Ort, auf dem du stehst, ist heiliger Boden."',
        6: 'Und er sprach: "Ich bin der Schutzgott deiner Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs." Da verbarg Moses sein Antlitz; denn er scheute sich, auf Gott zu blicken.',
        7: 'Der Herr aber sprach: "Die Quälung meines Volkes in Ägypten habe ich wohl bemerkt und sein Schreien über seine Fronvögte gehört. Ich kenne seine Leiden.',
        8: 'So fuhr ich denn herab, es aus Ägyptens Hand zu lösen und es aus diesem Lande hinaufzuführen in ein Land, trefflich und weit, in ein Land, das von Milch und Honig fließt, zu dem Sitze der Kanaaniter und Chittiter, der Amoriter, Periziter, Chiwiter und Jebusiter.',
        9: 'Nun ist das Geschrei der Söhne Israels zu mir gedrungen, und ich habe die Quälerei gesehen, mit der die Ägypter sie quälen.',
        10: 'So geh! Ich sende dich zu Pharao. Und führe mein Volk, die Söhne Israels, aus Ägypten!"',
        11: 'Moses aber sprach zu Gott: "Wer bin ich, daß ich zu Pharao gehe und die Söhne Israels aus Ägypten führe?"',
        12: 'Er sprach: "Ich selber werde ja mit dir sein. Dies sei für dich das Zeichen, daß ich dich sende. Führst du das Volk aus Ägypten, dann feiert ihr auf diesem Berge ein Fest zu Gottes Ehren."',
        13: 'Da sprach Moses zu Gott: "Ich komme also zu den Söhnen Israels und sage ihnen: \'Der Schutzgott eurer Väter schickt mich zu euch.\' Wenn sie mich fragen: \'Was ist es um seinen Namen?\' was soll ich ihnen sagen?"',
        14: 'Da sprach Gott zu Moses: "Ich bin der \'Ich bin\'." Und er sprach: "So sollst du zu den Söhnen Israels sprechen: \'Der "Ich bin" hat mich zu euch gesandt.\'"',
        15: 'Und weiter sprach Gott zu Moses: "So sollst du zu den Söhnen Israels sprechen: \'Der Herr, der Schutzgott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, schickt mich zu euch.\' Für ewig ist dies mein Name und dies für alle Geschlechter meine Bezeichnung.',
        16: 'Geh! Versammle die Ältesten in Israel und sprich zu ihnen: Der Herr, der Schutzgott eurer Väter, ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, mit der Zusage: Ich achte genau auf euch und auf das, was euch in Ägypten geschieht.',
        17: 'Und ich sage nun: Ich führe euch aus Ägyptens Elend weg in das Land der Kanaaniter, Chittiter, Amoriter, Periziter, Chiwiter und Jebusiter, in ein Land, von Milch und Honig fließend.',
        18: "Und hören sie auf dich und kommst du mit den Ältesten Israels zum König von Ägypten, dann sagt ihr zu ihm: 'Der Herr, der Schutzgott der Hebräer, ist uns begegnet. Nun möchten wir drei Tagereisen in die Wüste ziehen und dort dem Herrn, unserem Gott, opfern.'",
        19: 'Ich aber weiß, daß nur unter starkem Druck Ägyptens König euch ziehen läßt.',
        20: 'So recke ich denn meine Hand aus und schlage Ägypten mit all meinen Wundem, die ich darin wirken werde. Daraufhin läßt er euch ziehen.',
        21: 'Und ich verschaffe diesem Volke bei den Ägyptern Wohlwollen, daß ihr nicht leer abzieht, wenn ihr geht.',
        22: 'Die Weiber sollen sich von ihren Nachbarinnen und von ihren Hausgenossinnen Gold- und Silberschmuck ausbitten und Gewände! Dann legt sie euren Söhnen und Töchtern an und gewinnt so die Ägypter!"',
    },
    4: {
        1: 'Moses erwiderte und sprach: "Wenn sie mir aber nicht glauben und nicht auf mich hören, sondern sprechen: \'Der Herr ist dir nicht erschienen\'?"',
        2: 'Da sprach der Herr zu ihm: "Was hast du da in deiner Hand?" Er sprach: "Einen Stab."',
        3: 'Da sprach er: "Wirf ihn zur Erde!" Er warf ihn zur Erde. Da ward er eine Schlange, so daß Moses vor ihr floh.',
        4: 'Da sprach der Herr zu Moses: "Streck deine Hand aus! Greif sie am Schwanze!" Er reckte seine Hand aus und packte sie. Da ward sie in seiner Hand zum Stabe.',
        5: '"Dies sei, damit sie glauben, daß der Herr, der Schutzgott ihrer Väter, dir erschienen ist, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs."',
        6: 'Der Herr sprach weiter zu ihm: "Bringe deine Hand in deinen Busen!" Da brachte er seine Hand in den Busen, und als er sie hervorzog, war seine Hand aussätzig wie Schnee.',
        7: 'Er sprach: "Tu deine Hand wieder in deinen Busen!" Da tat er seine Hand wieder in seinen Busen und zog sie wieder aus seinem Busen. Da war sie wieder gleich dem anderen Fleische geworden.',
        8: '"Wollen sie dir nicht glauben und nicht auf des ersten Zeichens Sprache hören, dann glauben sie der Sprache dieses letzten Zeichens.',
        9: 'Und glauben sie nicht diesen beiden Zeichen und hören sie nicht auf dich, dann nimmst du von dem Nilwasser und gießest es auf das Trockene. Dann wird das Wasser, das du dem Nil entnimmst, auf dem Trockenen zu Blut."',
        10: 'Moses sprach zum Herrn: "Herr! Mit Verlaub! Ich bin kein Mann der Rede. Nicht gestern, nicht ehegestern und auch heute nicht, seit du mit deinem Diener sprichst. Ich bin unbeholfen mit Mund und Zunge."',
        11: 'Da sprach der Herr zu ihm: "Wer kann dem Menschen einen Mund geben? Wer kann ihn stumm oder taub machen? Wer sehend oder blind? Bin es nicht ich, der Herr?',
        12: 'Und nun geh! Ich will schon mit deinem Munde sein; dann lehre ich dich, was du reden sollst."',
        13: 'Er aber sprach: "Herr! Mit Verlaub! Bestelle es lieber durch jemand anderen!"',
        14: 'Da ward der Herr über Moses zornig und sprach: "Ist nicht dein Bruder Aaron, der Levite, da? Ich weiß, daß er gut reden kann. Zudem geht er dir gerade entgegen. Und so er dich sieht, freut er sich herzlich.',
        15: 'Dann sprich mit ihm und lege ihm die Worte in den Mund! Ich aber will mit deinem und seinem Munde sein, und so lehre ich euch, was ihr tun sollt.',
        16: 'Er selber redet nun für dich zum Volk. So dient er dir zum Mund, und du bist ihm zu einem Gott.',
        17: 'Und diesen Stab sollst du in die Hand nehmen, um mit ihm die Zeichen zu tun."',
        18: 'Moses ging und kehrte wieder zu seinem Schwiegervater Jetro und sprach zu ihm: "Ich möchte gehen und wieder zu meinen Brüdern in Ägypten kehren und sehen, ob sie noch leben." Jetro sprach zu Moses: "Geh in Frieden!"',
        19: 'Der Herr aber hatte zu Moses in Midian gesprochen: "Geh! Kehr wieder nach Ägypten! Denn alle Männer sind gestorben, die dir nach dem Leben trachteten."',
        20: 'So nahm Moses sein Weib und seine Söhne, setzte sie auf den Esel und kehrte wieder nach Ägypten. Auch den Gottesstab nahm Moses mit.',
        21: 'Da sprach der Herr zu Moses: "Da du wieder nach Ägypten kehrst, sieh zu, daß du all diese Wunder, die ich in deine Macht gelegt, vor Pharao tust! Ich aber verhärte sein Herz, daß er das Volk nicht entläßt.',
        22: "Dann sprich zu Pharao: 'So spricht der Herr: Mein erstgeborener Sohn ist Israel!",
        23: 'Ich sage dir: Entlaß meinen Sohn, daß er mich verehre! Doch weigerst du dich, ihn zu entlassen, dann erschlage ich deinen erstgeborenen Sohn.\'"',
        24: 'Unterwegs aber in der Herberge stieß der Herr auf ihn und wollte ihn töten.',
        25: 'Da nahm Sippora einen Kiesel, beschnitt die Vorhaut ihres Sohnes, rührte damit an seine Füße und sprach: "Du bist mir ein Blutmahner."',
        26: 'Da ließ er von ihm ab. Damals hatte sie gesagt "Blutmahner" wegen der Beschneidung.',
        27: 'Und der Herr sprach zu Aaron: "Geh Moses entgegen in die Wüste!" So ging er und traf ihn am Gottesberge und küßte ihn.',
        28: 'Dann erzählte Moses dem Aaron alle seine Aufträge, die ihm der Herr gegeben, und alle Zeichen, die er ihm anbefohlen hatte.',
        29: 'Da gingen Moses und Aaron und versammelten alle Ältesten der Israeliten.',
        30: 'Und Aaron verkündete alle Aufträge, die der Herr dem Moses gegeben. Und der tat die Zeichen vor den Augen des Volkes.',
        31: 'Da glaubte das Volk. Und als es hörte, daß der Herr sich der Söhne Israels angenommen und ihr Elend gesehen habe, verneigten sie sich und warfen sich nieder.',
    },
    5: {
        1: 'Hernach kamen Moses und Aaron und sprachen zu Pharao: "So spricht der Herr, der Gott Israels: \'Entlaß mein Volk, daß sie mir ein Fest in der Wüste feiern!\'"',
        2: 'Da sprach Pharao: "Wer ist der Herr, daß ich ihm gehorchen und Israel entlassen soll? Den Herrn kenne ich nicht, und Israel entlasse ich nicht."',
        3: 'Sie sprachen.- "Der Gott der Hebräer ist uns begegnet. Wir möchten nur drei Tagereisen in die Wüste gehen und dem Herrn, unserem Gott, opfern, daß er uns nicht mit Pest oder Schwert überfalle!"',
        4: 'Da sprach der König von Ägypten zu ihnen: "Warum wollt ihr, Moses und Aaron, das Volk an seiner Arbeit hindern? Kümmert euch doch um eure Sachen!"',
        5: 'Und Pharao sprach: "Fürwahr, allzuviel Leute sind schon im Land. Da lasset ihr diese von ihren Arbeiten ausruhen!"',
        6: 'Und Pharao befahl am gleichen Tage des Volkes Fronvögten und seinen Aufsehern:',
        7: '"Liefert kein Stroh mehr dem Volk zum Ziegelmachen wie bisher! Selber sollen sie gehen und Stroh auflesen!',
        8: "Aber den Satz der Ziegel, die sie bisher hergestellt, belaßt für sie! Macht keinen Abzug daran! Faul sind sie, drum schreien sie: 'Laßt uns gehen, unserem Gott zu opfern!'",
        9: 'Wuchtig laste die Arbeit auf diesen Leuten, und sie sollen daran zu tun haben, daß sie nicht auf Lügenreden achten!"',
        10: 'Da kamen des Volkes Fronvögte und seine Aufseher heraus und sagten zum Volke: "So spricht der Pharao: Ich liefere euch kein Stroh mehr.',
        11: 'Geht selber! Holt euch Stroh, wo ihr es findet! Von eurem Frondienst aber wird nichts gekürzt"',
        12: 'Da zerstreute sich das Volk über ganz Ägypterland, Stoppeln für die Ziegel zu sammeln.',
        13: 'Aber die Fronvögte drängten und sprachen: "Die volle Arbeit müßt ihr täglich liefern wie damals, als es Stroh gab."',
        14: 'Da wurden die israelitischen Aufseher gezüchtigt. Ihnen hatten Pharaos Fronvögte die Schuld gegeben, indem sie sprachen: "Warum habt ihr nicht euer Maß an Ziegeln wie bisher, so auch heute fertig gebracht?"',
        15: 'So kamen die israelitischen Aufseher, schrien zu Pharao und sprachen: "Warum tust du so mit deinen Sklaven?',
        16: 'Stroh wird deinen Sklaven nicht mehr geliefert; doch \'Ziegel\', sagt man uns, \'liefert ab!\' Nun werden deine Sklaven schwer gezüchtigt, indes an dir die Schuld liegt."',
        17: 'Er sprach: "Faul seid ihr, faul. Deshalb sagt ihr: \'Wir wollen gehen, dem Herrn zu opfern.\'',
        18: 'Jetzt marsch! Fort an die Arbeit! Stroh wird euch nicht geliefert; doch den Satz an Ziegeln habt ihr zu liefern."',
        19: 'Da sahen die Aufseher der Israeliten sie traurig an und sprachen: "Ihr dürft das Tagwerk an Ziegeln nicht kürzen."',
        20: 'Als sie von Pharao weggingen, trafen sie auf Moses und Aaron, die sie erwarteten.',
        21: 'Sie sprachen zu ihnen: "Der Herr blicke auf euch und richte, daß ihr uns bei Pharao und seinen Dienern in übelsten Geruch gebracht, ja ihnen das Schwert in die Hand gedrückt habt, uns zu morden!"',
        22: 'Da wandte sich Moses an den Herrn und sprach: "Herr! Warum tust du diesem Volk so übel? Wozu hast du mich hergesandt?',
        23: 'Seit ich zu Pharao gekommen bin, in deinem Namen zu reden, hat er diesem Volke übel getan, und du hast dein Volk nicht davor geschützt."',
    },
    6: {
        1: 'Da sprach der Herr zu Moses: "Jetzt wirst du sehen, was ich an Pharao tun werde. Gezwungen läßt er sie ausziehen und gezwungen jagt er sie aus seinem Land."',
        2: 'Und Gott redete mit Moses und sprach zu ihm: "Ich bin der Herr.',
        3: 'Ich erschien Abraham, Isaak und Jakob als allmächtiger Gott; aber mit meinem Namen "Herr" habe ich mich ihnen nicht bekannt gemacht.',
        4: 'Wie ich meinen Bund mit ihnen errichtet habe, das Land Kanaan ihnen zu geben, das Land, in dem sie zu Gast geweilt,',
        5: 'so habe ich auch das Gestöhn der Söhne Israels gehört, die die Ägypter knechten. Und ich gedachte meines Bundes.',
        6: "Daher sprich zu den Söhnen Israels: 'Ich bin der Herr. Ich befreie euch nun vom Frondienst der Ägypter und reiße euch aus ihrer Sklaverei. Ich erlöse euch mit hochgerecktem Arme und gewaltigen Gerichten.",
        7: 'Ich nehme euch mir zum Volk und bin euch ein Schutzgott. Da erfahret ihr, daß nur ich der Herr bin, euer Gott, der euch befreit vom Frondienst der Ägypter.',
        8: 'Ich bringe euch dann in das Land, das ich Abraham, Isaak und Jakob durch feierlichen Schwur verheißen. Ich gebe es euch zum Erbbesitz, ich der Herr.\'"',
        9: 'Und Moses berichtete dies den Israeliten. Aber sie hörten nicht auf Moses in ihrer gedrückten Stimmung und wegen der schweren Arbeit.',
        10: 'Da sprach der Herr zu Moses also:',
        11: '"Geh! Sprich mit Pharao, dem König von Ägypten, er soll die Söhne Israels aus seinem Land entlassen!"',
        12: 'Da redete Moses vor dem Herrn also: "Haben die Israeliten nicht auf mich gehört, wie sollte Pharao auf mich hören? Ich bin ja nicht gewandt im Reden."',
        13: 'Da redete der Herr mit Moses und Aaron und entbot sie zu den Israeliten und zu Pharao, dem König von Ägypten, um die Israeliten aus Ägypterland zu führen.',
        14: 'Dies sind ihre Familienhäupter: Die Söhne Rubens, des Erstgeborenen Israels, waren Chanok, Pallu, Chesron und Karmi. Dies sind die Geschlechter Rubens.',
        15: 'Simeons Söhne waren Jemuel, Jamin, Ohad, Jakin, Sochar und Saul, der Kanaaniterin Sohn. Dies sind die Sippen Simeons.',
        16: 'Dies sind die Namen der Söhne Levis nach ihrem Stammbaum: Gerson, Kehat und Merari. Levi ward 137 Jahre alt.',
        17: 'Gersons Söhne waren Libni und Simi mit ihren Sippen.',
        18: 'Kehats Söhne waren Amram, Ishar, Chebron und Uzziel. Kehat ward 133 Jahre alt.',
        19: 'Meraris Söhne waren Machli und Musi. Dies sind die Sippen der Leviten nach ihrem Stammbaum.',
        20: 'Amram heiratete seine Tante Jokebed. Sie gebar ihm Aaron und Moses; Amram ward 137 Jahre alt.',
        21: 'Ishars Söhne waren Korach, Nepheg und Zikri.',
        22: 'Uzziels Söhne waren Misael, Elsaphan und Sitri.',
        23: 'Und Aaron heiratete Aminadabs Tochter Eliseba, des Nachson Schwester. Sie gebar ihm Nadab und Abihu, Eleazar und Itamar.',
        24: 'Korachs Söhne waren Assir, Elkana und Abiasaph. Dies sind die Sippen der Korachiter.',
        25: 'Aarons Sohn Eleazar hatte eine der Töchter Putiels geheiratet. Sie gebar ihm Pinechas. Dies sind die Familienhäupter der Leviten nach ihren Sippen.',
        26: 'So war es mit Aaron und Moses, zu denen der Herr gesprochen: "Führt die Söhne Israels in ihren Scharen aus Ägypterland!"',
        27: 'Sie sind es, die mit dem König von Ägypten, Pharao, redeten, um die Israeliten aus Ägypten zu führen. So war es mit Moses und Aaron.',
        28: 'So war es an dem Tage, da der Herr mit Moses im Lande Ägypten gesprochen.',
        29: 'Der Herr sprach zu Moses also: "Ich bin der Herr. Vermelde Pharao, dem König von Ägypten, alles, was ich dir sage!"',
        30: 'Da sprach Moses vor dem Herrn: "Siehe! Ich bin im Reden ungewandt. Wie soll da Pharao auf mich hören?"',
    },
    7: {
        1: 'Da sprach der Herr zu Moses: "Siehe, ich mache dich für Pharao zu einem Gott, und dein Bruder Aaron ist dein Prophet.',
        2: 'Alles, was ich dir auftrage, sollst du sagen. Doch zu Pharao sage dein Bruder Aaron, er solle die Söhne Israels aus seinem Lande entlassen!',
        3: 'Ich aber will Pharaos Herz verhärten und im Ägypterland meine Zeichen und meine Wunder mehren.',
        4: 'So hört Pharao nicht auf euch, bis ich meine Hand auf Ägypten lege und aus Ägypterland meine Scharen, mein Volk, die Söhne Israels, führe, unter großen Machterweisen.',
        5: 'Dann erfahren die Ägypter, daß ich der Herr bin, wenn ich meine Hand gen Ägypten strecke und aus seiner Mitte die Söhne Israels führe."',
        6: 'Moses und Aaron taten so. Wie es der Herr sie hieß, so taten sie.',
        7: 'Moses aber war 80 Jahre alt und Aaron 83, als sie mit Pharao verhandelten.',
        8: 'Und der Herr sprach zu Moses und Aaron also:',
        9: '"Spricht Pharao zu euch: \'Gebt euren Erweis\', dann sprich zu Aaron: \'Nimm deinen Stab und wirf ihn vor Pharao, daß er zur Natter werde!\'"',
        10: 'Da kamen Moses und Aaron zu Pharao und taten, wie der Herr befohlen. Aaron warf seinen Stab vor Pharao und seine Diener; da ward er zur Natter.',
        11: 'Aber auch Pharao berief die Weisen und Zauberer, und Ägyptens Zauberkünstler taten so mit ihren Künsten.',
        12: 'Sie warfen jeder seinen Stab hin, und diese wurden zu Nattern. Doch Aarons Stab verschlang ihre Stäbe.',
        13: 'Aber Pharaos Herz blieb verhärtet; hatte er doch nicht auf sie gehört, wie der Herr vorausgesagt.',
        14: 'Und der Herr sprach zu Moses: "Des Pharao Herz ist verstockt. Er weigert sich, das Volk zu entlassen.',
        15: 'Geh morgen früh zu Pharao! Da geht er an das Wasser. Dann tritt ihm am Nilufer entgegen. Den Stab, der sich zur Schlange wandelt, nimm mit dir!',
        16: 'Dann sprich zu ihm: \'Der Herr, der Schutzgott der Hebräer, sendet mich zu dir mit der Weisung: "Entlaß mein Volk, daß sie in der Wüste mir zu Ehren ein Fest feiern!" Aber bis jetzt hast du nicht hören wollen.',
        17: 'Nun spricht der Herr: "Daran sollst du erkennen, daß ich der Herr bin: Siehe, ich schlage mit dem Stab in meiner Hand auf das Wasser im Nil, dann wandelt dieses sich in Blut.',
        18: 'Die Fische im Nil sterben, und der Nil wird stinkend; dann ekelt es die Ägypter, Wasser aus dem Nil zu trinken."\'"',
        19: 'Und der Herr sprach zu Moses: "Sprich zu Aaron: \'Nimm deinen Stab und strecke deine Hand über die Gewässer in Ägypten, über ihre Flüsse, Kanäle, Teiche und alle ihre Wasserstellen, daß sie zu Blut werden!\' Dann ist Blut im ganzen Land Ägypten, im Holzgefäß wie im Steinzeug."',
        20: 'Da taten Moses und Aaron so, wie der Herr befohlen. Er hob den Stab und schlug das Wasser im Nil vor Pharaos und seiner Diener Augen. Da ward alles Wasser im Nil zu Blut.',
        21: 'Die Fische im Nil starben; der Nil ward stinkend; da konnten die Ägypter kein Wasser aus dem Nil trinken. Blut war im ganzen Lande Ägypten.',
        22: 'Aber auch Ägyptens Zauberkünstler taten ebenso mit ihren Zaubereien. So blieb Pharaos Herz verstockt; hatte er doch nicht auf sie gehört, wie es der Herr vorhergesagt.',
        23: 'Und Pharao wandte sich und trat in sein Haus, hatte er sich doch auch dies nicht zu Herzen genommen.',
        24: 'Alle Ägypter gruben nun rings um den Nil nach Trinkwasser, weil sie vom Nilwasser nicht trinken konnten.',
        25: 'So vergingen volle sieben Tage, nachdem der Herr den Nil geschlagen hatte. Da sprach der Herr zu Moses: "Geh zu Pharao hinein! Dann sagst du ihm: \'So spricht der Herr: "Entlasse mein Volk, daß sie mich verehren! Willst du es aber nicht entlassen, dann plage ich dein ganzes Gebiet mit Fröschen. Von Fröschen wimmelt dann der Nil. Sie steigen heraus und kommen in dein Haus, in dein Schlafgemach, auf dein Bett und in deiner Diener und in deines Volkes Häuser, in deine Backöfen und Teigmulden. Selbst an dir, wie an deinem Volke und an allen deinen Dienern, werden die Frösche hinaufsteigen."\'"',
    },
    8: {
        1: 'Und der Herr sprach zu Moses: "Sprich jetzt zu Aaron: \'Streck deine Hand mit deinem Stab über die Flüsse, Kanäle und Teiche und laß die Frösche über Ägypterland aufsteigen!\'"',
        2: 'Da streckte Aaron seine Hand über Ägyptens Gewässer. Da kamen die Frösche und bedeckten das Land Ägypten.',
        3: 'Aber auch die Zauberkünstler taten ebenso mit ihren Zaubereien. Auch sie ließen Frösche über das Land Ägypten kommen.',
        4: 'Pharao aber rief Moses und Aaron herbei und sprach: "Leget Fürbitte beim Herrn ein, daß er die Frösche mir und meinem Volke nehme! Dann entlasse ich das Volk, daß es dem Herrn opfere."',
        5: 'Da sprach Moses zu Pharao: "Sag mir: Auf wann soll ich für dich, deine Diener und dein Volk beten, daß die Frösche von dir und deinen Häusern weichen und nur im Nile bleiben?"',
        6: 'Da sprach er: "Auf morgen." Er sprach: "Nach deinem Worte geschehe, daß du erkennst: Keiner ist wie der Herr, unser Gott.',
        7: 'Dann weichen Frösche von dir und deinen Häusern, von deinen Dienern und von deinem Volke und sollen nur noch im Nil bleiben."',
        8: 'So gingen Moses und Aaron von Pharao. Und Moses rief zum Herrn wegen des Versprechens, das er der Frösche halber dem Pharao gemacht.',
        9: 'Und der Herr tat nach Mosis Wort. Die Frösche starben weg aus den Häusern, den Gehöften und Feldern.',
        10: 'Man schüttete sie zu Haufen und das Land roch übel.',
        11: 'Als Pharao aber sah, daß Erleichterung geworden, verstockte er sein Herz, hatte er doch nicht mehr auf sie gehört, wie es der Herr vorhergesagt.',
        12: 'Da sprach der Herr zu Moses: "Sprich zu Aaron: \'Streck deinen Stab aus! Schlag auf dem Boden den Staub! Dann wird er in ganz Ägypterland zu Mücken.\'"',
        13: 'Und sie taten so. Aaron streckte seine Hand mit dem Stab aus und schlug den Staub auf dem Boden. Da kamen Stechmücken an Mensch und Vieh. Aller Staub auf dem Boden war zu Stechmücken im Lande Ägypten geworden.',
        14: 'Da taten die Zauberkünstler ebenso mit ihren Zaubereien, die Stechmücken wegzubringen; aber dies konnten sie nicht. Die Stechmücken gingen an Mensch und Vieh.',
        15: 'Da sprachen die Zauberkünstler zu Pharao: "Dies ist Gottes Finger." Doch Pharaos Herz blieb verhärtet, hatte er doch nicht auf sie gehört, wie es der Herr vorhergesagt.',
        16: 'Und der Herr sprach zu Moses: "Morgen in der Frühe tritt vor Pharao, wenn er ans Wasser geht, und sprich zu ihm: \'So spricht der Herr: "Entlasse mein Volk, daß es mich verehre!',
        17: 'Entlässest du aber mein Volk nicht, dann lasse ich über dich, deine Diener, dein Volk und deine Häuser Fliegen kommen. Die Häuser der Ägypter werden voll von Fliegen, sowie das Ackerfeld, darauf sie sind.',
        18: 'Aber ausnehmen will ich an jenem Tage das Land Gosen, wo mein Volk weilt, daß dort keine Fliegen seien, damit du erkennest, daß ich Herr inmitten dieses Landes bin.',
        19: 'Diesen Unterschied mache ich zwischen meinem Volke und deinem Volke. Morgen geschieht dies Zeichen."\'"',
        20: 'Und der Herr tat so. Hundsfliegen, eine schwere Menge, kamen in das Haus Pharaos und in das seiner Diener und über ganz Ägypterland; so ward durch die Hundsfliegen das Land verderbt.',
        21: 'Da rief Pharao nach Moses und Aaron und sprach: "Geht! Opfert eurem Gott im Lande!"',
        22: 'Da sprach Moses: "Nicht richtig wäre es, so zu tun. Was den Ägyptern ein Greuel ist, opfern wir dem Herrn, unserem Gott. Brächten wir zum Opfer, was den Ägyptern greulich dünkt, würden sie uns nicht steinigen?',
        23: 'Wir möchten in die Wüste drei Tagesreisen ziehen und dem Herrn, unserem Gott, opfern, wie der Herr uns geboten hat."',
        24: 'Da sprach Pharao: "Nun, ich lasse euch ziehen, dann könnt ihr dem Herrn, eurem Gott, in der Wüste opfern. Nur nicht zu weit entfernet euch! Legt für mich Fürsprache ein!"',
        25: 'Da sprach Moses: "Sowie ich von dir weggehe, lege ich Fürsprache beim Herrn ein. Morgen weichen von Pharao, seinen Dienern und seinem Volke die Fliegen. Nur möge Pharao nicht weiter trügen, daß er das Volk nicht zum Opfer für den Herrn entläßt!"',
        26: 'Da ging Moses von Pharao weg und legte Fürbitte beim Herrn ein.',
        27: 'Und der Herr tat nach Mosis Wort. Die Fliegen wichen von Pharao, seinen Dienern und seinem Volke; nicht eine blieb zurück.',
        28: 'Aber Pharao verstockte sein Herz auch diesmal. Er ließ das Volk nicht ziehen.',
    },
    9: {
        1: 'Da sprach der Herr zu Moses: "Geh zu Pharao hinein! Dann sprich zu ihm: \'So spricht der Herr, der Schutzgott der Hebräer: Entlaß mein Volk, daß sie mich verehren!',
        2: 'Verweigerst du aber die Freilassung und hältst sie weiter fest,',
        3: 'dann kommt die Hand des Herrn zum Verderben an dein Vieh auf dem Felde, an Pferde, Esel, Kamele, Rinder und Schafe, eine schrecklich schwere Seuche.',
        4: 'Aber einen Unterschied macht der Herr zwischen Israels Vieh und dem Ägyptens: Keinem Israeliten stirbt ein Stück.\'"',
        5: 'Und der Herr bestimmte eine Zeit, indem er sprach: "Morgen schon tut dies der Herr an dem Lande."',
        6: 'Und der Herr tat dies am folgenden Tage. Alles Vieh der Ägypter fiel; aber vom Vieh der Israeliten fiel nicht eines.',
        7: 'Da ließ Pharao nachsehen. Und von Israels Vieh war auch nicht eines gefallen. Doch Pharaos Herz verstockte sich, und er entließ das Volk nicht.',
        8: 'Da sprach der Herr zu Moses und Aaron: "Füllt eure Hände jetzt mit Ofenruß! Und Moses streue ihn himmelwärts vor Pharaos Augen!',
        9: 'Dann wird er zu feinem Staube über ganz Ägypten und wird an Mensch und Tier in ganz Ägypten zu Beulen, und diese brechen schwärend auf."',
        10: 'Da nahmen sie Ofenruß, traten vor Pharao, und Moses streute ihn himmelwärts. Da wurden schwärende Beulen, die aufbrachen, an Mensch und Vieh.',
        11: 'Die Zauberkünstler aber konnten nicht vor Moses stehen wegen der Beulen; denn an den Zauberkünstlern, wie an allen Ägyptern, waren die Beulen.',
        12: 'Der Herr aber verhärtete Pharaos Herz, hatte er doch nicht auf sie gehört, wie es der Herr dem Moses vorhergesagt.',
        13: 'Da sprach der Herr zu Moses: "In aller Frühe tritt morgen vor den Pharao und sprich zu ihm: So spricht der Herr, der Schutzgott der Hebräer: \'Entlasse mein Volk, daß sie mich verehren!',
        14: 'Denn diesmal schicke ich alle meine Plagen auch zu dir wie zu deinen Dienern und deinem Volke, daß du erkennest: Keiner ist auf der ganzen Erde wie ich.',
        15: 'Schon jetzt könnte ich meine Hand ausstrecken und dich samt deinem Volke mit Seuchen schlagen, daß du von der Erde schwändest.',
        16: 'Ich lasse dich doch gerade deshalb leben, damit ich dir meine Macht zeige, damit man auf der ganzen Erde meinen Ruhm künde.',
        17: 'Hältst du aber weiterhin mein Volk zurück und willst es nicht entlassen,',
        18: 'dann lasse ich morgen um diese Zeit einen überschweren Hagel niedergehen, desgleichen nicht in Ägypten war seit seiner Gründungszeit bis jetzt.',
        19: 'Nun schick hin und birg dein Vieh und alles, was du auf dem Felde hast! All die Menschen und Tiere, die auf dem Felde betroffen werden und nicht unter Dach kommen, sterben, geht der Hagel auf sie nieder.\'"',
        20: 'Wer nun von Pharaos Höflingen das Wort des Herrn achtete, der flüchtete seine Sklaven und sein Vieh unter Dach.',
        21: 'Wer aber des Herrn Wort mißachtete, der ließ seine Sklaven und sein Vieh auf dem Felde.',
        22: 'Da sprach der Herr zu Moses: "Streck deine Hand gen Himmel, daß Hagel in ganz Ägypterland falle auf Mensch und Vieh und alles Feldgewächs im Lande Ägypten!"',
        23: 'Und Moses streckte seinen Stab gen Himmel. Da ließ der Herr Donner und Hagel kommen, und Feuer ging nieder. So ließ der Herr Hagel auf das Land Ägypten fallen.',
        24: 'Ein Hagel war es, und mitten im Hagel ein Flugfeuer, übermächtig. Seinesgleichen war nie über ganz Ägypterland gekommen, seitdem es ein Volk geworden.',
        25: 'Und der Hagel schlug im ganzen Land Ägypten alles auf dem Felde, Mensch und Vieh. Auch alles Feldgewächs schlug der Hagel und zerschmetterte alle Bäume des Feldes.',
        26: 'Nur in dem Lande Gosen, wo die Israeliten waren, fiel kein Hagel.',
        27: 'Da sandte Pharao, berief Moses und Aaron und sprach zu ihnen: "Diesmal habe ich gefehlt. Der Herr ist im Recht; ich aber und mein Volk sind im Unrecht.',
        28: 'Legt bei dem Herrn Fürsprache ein! Übergenug des Gottesdonners und des Hagels! Ich lasse euch frei. Ihr sollt nicht länger verweilen."',
        29: 'Da sprach Moses zu ihm: "Sobald ich aus der Stadt gehe, breite ich zum Herrn meine Hände. Das Donnern wird aufhören, und der Hagel nicht mehr sein, daß du erkennest: Dem Herrn gehört die Erde.',
        30: 'Doch du und deine Diener fürchten noch nicht den Herrn, Gott, wie ich wohl weiß."',
        31: 'Der Flachs und die Gerste waren zerschlagen worden; denn die Gerste stand in Ähren, und der Flachs in Blüte.',
        32: 'Weizen aber und Spelt waren nicht zerschlagen worden, weil sie spät sind.',
        33: 'Moses ging nun von Pharao zur Stadt hinaus und breitete seine Hände zum Herrn. Da hörte Donnern und Hageln auf; auch der Regen goß nicht mehr auf die Erde.',
        34: 'Als aber Pharao sah, daß Regen, Hagel und Donner aufgehört, verharrte er in seiner Sünde und verstockte sein Herz, samt seinen Dienern.',
        35: 'Und Pharaos Herz verhärtete sich, und so ließ er die Israeliten nicht ziehen, wie es der Herr durch Moses vorhergesagt.',
    },
    10: {
        1: 'Da sprach der Herr zu Moses: "Geh hinein zu Pharao! Habe ich doch sein und seiner Diener Herz verstockt, daß ich diese Zeichen bei ihm tue,',
        2: 'und daß du Kind und Kindeskindern erzählen kannst, wie ich mich an Ägypten ausgewirkt und welche Zeichen ich an ihnen getan habe. So könnt ihr erkennen, daß ich der Herr bin."',
        3: 'Da kamen Moses und Aaron zu Pharao und sprachen zu ihm: "So spricht der Herr, der Schutzgott der Hebräer: \'Wie lange willst du dich nicht vor mir beugen? Entlasse mein Volk, daß es mir diene!',
        4: 'Weigerst du dich aber, mein Volk zu entlassen, dann bringe ich morgen Heuschrecken in dein Gebiet.',
        5: 'Dann decken sie des Landes Oberfläche, daß man den Boden nicht mehr sieht. Sie fressen dann den Rest, der vom Hagel übrig ist, und sie fressen alle Bäume ab, die euch im Felde sprießen.',
        6: 'Voll werden davon deine Häuser, all deiner Diener Häuser und die ganz Ägyptens, wie es deine Väter nicht geschaut noch deine Großväter, seit ihrem Erdenwallen bis zu diesem Tag.\'" Und er wandte sich und ging weg von Pharao.',
        7: 'Da sprachen Pharaos Diener zu ihm: "Wie lange soll dieser uns eine Gefahr sein? Entlasse die Männer, daß sie dem Herrn, ihrem Gott, dienen! Siehst du nicht, daß Ägypten verdirbt?"',
        8: 'Da wurden Moses und Aaron zu Pharao zurückgeholt, und er sprach zu ihnen: "Geht! Dienet dem Herrn, eurem Gott! Doch wer geht mit?"',
        9: 'Da sprach Moses: "Mit unseren Jünglingen und unseren Greisen wollen wir ziehen, mit unseren Söhnen und Töchtern; mit unseren Schafen und Rindern wollen wir ziehen. Wir haben ja ein Fest des Herrn zu feiern."',
        10: 'Da sprach er zu ihnen: "Möge der Herr so bei euch sein, wie ich euch mit euren Kindern fortlasse! Seht, daß ihr Böses im Sinne habt!',
        11: 'Daraus wird nichts. Ihr Männer geht und verehrt den Herrn! Das war euer Begehr." Und man jagte sie von Pharao fort.',
        12: 'Da sprach der Herr zu Moses: "Recke deine Hand über das Ägypterland, der Heuschrecken wegen! Sie sollen über das Land Ägypten kommen und im Lande alles Gewächs abfressen, das der Hagel hat stehen lassen."',
        13: 'Da streckte Moses seinen Stab über das Ägypterland. Und der Herr führte einen Ostwind über das Land jenen ganzen Tag und die ganze Nacht. Morgen ward es; da hatte der Ostwind die Heuschrecken hergetragen.',
        14: 'So kamen die Heuschrecken über ganz Ägypterland und fielen im ganzen Bereich Ägyptens übermächtig ein. Nie gab es vorher soviel Heuschrecken, noch wird es später soviel geben.',
        15: 'Sie deckten des ganzen Landes Oberfläche, daß der Boden nicht mehr zu sehen war. Sie fraßen alles Gewächs im Lande und alle Baumfrüchte, die der Hagel hatte stehen lassen. Nichts Grünes blieb mehr an den Bäumen und Feldgewächsen im Ägypterland.',
        16: 'Eilends ließ Pharao Moses und Aaron rufen und sprach: "Ich bin im Unrecht wider den Herrn, euren Gott, und wider euch.',
        17: 'Verzeiht mir doch noch diesmal mein Verschulden und legt bei dem Herrn, eurem Gott, Fürsprache ein, daß er nur diesen Tod von mir wende!"',
        18: 'Da ging er von Pharao weg und flehte zum Herrn.',
        19: 'Da ließ der Herr einen sehr starken Westwind wehen. Dieser nahm die Heuschrecken und warf sie ins Schilfmeer. Nicht eine Heuschrecke blieb in Ägyptens ganzem Bereiche.',
        20: 'Aber der Herr verstockte Pharaos Herz, und so entließ er die Israeliten nicht.',
        21: 'Und der Herr sprach zu Moses: "Recke deine Hand gen Himmel! Finsternis komme über Ägypterland, und die Finsternis sei stark!"',
        22: 'Da reckte Moses seine Hand gen Himmel, und eine dichte Finsternis ward in ganz Ägypterland, drei Tage lang.',
        23: 'Keiner sah den anderen und keiner erhob sich von seinem Platz, drei Tage lang. Die Israeliten alle aber hatten Licht in ihren Siedlungen.',
        24: 'Da rief Pharao nach Moses und sprach: "Geht! Verehrt den Herrn! Eure Schafe und Rinder aber bleiben hier. Doch eure Kinder gehen mit euch."',
        25: 'Da sprach Moses: "Auch du selbst solltest uns Schlacht- und Brandopfer liefern, daß wir sie für den Herrn, unseren Gott, zurichten.',
        26: 'Aber auch unser Vieh muß mit uns gehen. Nicht eine Klaue bleibe zurück! Davon müssen wir nehmen können, wenn wir dem Herrn, unserem Gott, zu Ehren ein Fest feiern wollen. Wir wissen ja nicht, wie wir den Herrn verehren sollen, bis wir dorthin kommen."',
        27: 'Aber der Herr verhärtete Pharaos Herz, und so wollte er sie nicht entlassen.',
        28: 'Und Pharao sprach zu ihm: "Geh weg von mir! Hüte dich, noch einmal mein Antlitz zu schauen! Sobald du mein Antlitz siehst, mußt du sterben."',
        29: 'Moses sprach: "Recht hast du geredet. Ich werde nicht wieder dein Antlitz schauen."',
    },
    11: {
        1: 'Und der Herr sprach zu Moses: "Noch eine Plage bringe ich über Pharao und Ägypten. Hernach läßt er euch von hier abziehen, und wenn er lediglich die Entlassung zugibt, dann jagt er euch gewaltsam fort.',
        2: 'Schärfe dem Volke ein, sie sollen, Männer wie Weiber, von den Bekannten silbernen und goldenen Schmuck erbitten!"',
        3: 'Und der Herr stimmte die Ägypter dem Volke günstig. Dazu galt der Mann Moses sehr viel in Ägypten, bei Pharaos Dienern wie beim Volke.',
        4: 'Da sprach Moses: "So spricht der Herr: \'Um Mitternacht fahre ich mitten durch Ägypten.',
        5: 'Dann stirbt im Lande Ägypten jeder Erstgeborene, von Pharaos Erstgeborenem an, der einst auf seinem Throne sitzen sollte, bis zu dem Erstgeborenen der Sklavin hinter der Handmühle, und alle Erstlingswürfe des Viehes.',
        6: 'Dann ist ein groß Gejammer im ganzen Lande Ägypten, desgleichen noch nie gewesen, noch je sein wird.',
        7: "Aber gegen keinen der Israeliten streckt ein Hund die Zunge heraus, weder gegen Mensch noch Vieh, daß ihr erkennet, wie der Herr zwischen Israel und Ägypten scheidet.'",
        8: 'Dann beugen sich alle diese deine Diener zu mir, werfen sich vor mir nieder und sprechen: \'Zieh weg, du samt dem ganzen Volke bei dir!\' Hernach ziehe ich weg." Und er ging von Pharao in loderndem Zorn.',
        9: 'Da sprach der Herr zu Moses: "Der Pharao hört nicht auf euch, damit sich meine Wunder mehren im Ägypterlande."',
        10: 'So hatten Moses und Aaron alle diese Wunder vor Pharao getan. Aber der Herr verhärtete Pharaos Sinn, daß er die Israeliten nicht aus seinem Lande entließ.',
    },
    12: {
        1: 'Und der Herr sprach zu Moses und Aaron im Lande Ägypten also:',
        2: '"Dieser Monat sei für euch der Anfangsmonat! Der Jahresmonde erster sei er für euch!',
        3: 'Sprecht so zu der Gesamtgemeinde Israels! Am zehnten dieses Monats nehme sich jedermann ein Lamm nach den Sippen, ein Lamm für jedes Haus!',
        4: 'Sind aber in einem Hause zuwenig für ein Lamm, dann nehme er es mit dem Nachbarn, der jenem gleich an Kopfsteuer ist! Jeder nach seinem Verzehr, sollt ihr zum Lamm beisteuern!',
        5: 'Ein fehlerfreies, männliches, noch nicht jähriges Lämmchen müßt ihr haben; aus den Schafen oder Ziegen sollt ihr es nehmen!',
        6: 'Dann verwahrt es bis zum vierzehnten des Monats! Dann schlachte es Israels Vollgemeinde abends!',
        7: 'Und vom Blute sollen sie nehmen und an beide Pfosten und den Türsturz tun, zum Schutze der Häuser, wo sie es essen!',
        8: 'Noch in derselben Nacht sollen sie das Fleisch essen, am Feuer gebraten, dazu ungesäuertes Brot. Mit Bitterkräutern sollen sie es essen!',
        9: 'Eßt nichts davon roh noch gargekocht, sondern gebraten, Kopf mit Beinen und Rumpf!',
        10: 'Laßt davon nichts bis zum Morgen übrig! Was bis zum Morgen übrigbleibt, sollt ihr verbrennen!',
        11: 'So sollt ihr es essen: Eure Hüften gegürtet, eure Schuhe an den Füßen, euren Stab in der Hand! Dann esset es in Hast: Ein Passah ist es dem Herrn.',
        12: 'Denn ich durchziehe in jener Nacht das Ägypterland und schlage alle Erstgeburt im Land Ägypten, Mensch und Vieh. Ich, der Herr, vollziehe das Gericht an Ägyptens Göttern allen.',
        13: 'Das Blut sei euch zum Zeichen an den Häusern, wo ihr weilt! Sehe ich das Blut, dann übergehe ich euch. Kein verderblicher Streich trifft euch, wenn ich das Land Ägypten schlage.',
        14: 'Zum Gedächtnis diene euch dieser Tag. Feiert ihn als ein Fest des Herrn in allen euren Geschlechtern! Als ewige Satzung sollt ihr ihn feiern!',
        15: 'Ihr sollt sieben Tage ungesäuertes Brot essen! Genau am ersten Tage sollt ihr aus euren Häusern Sauerteig entfernen - denn wer Gesäuertes ißt, ein solches Wesen werde aus Israel gestrichen! -, vom ersten bis zum siebten Tag.',
        16: 'Am ersten Tage sei heilige Versammlung! Am siebten haltet gleichfalls heilige Versammlung! Dabei darf keine Arbeit verrichtet werden. Nur was jeglich Wesen zu essen haben muß, das allein werde von euch bereitet!',
        17: 'Achtet diese Vorschrift! Denn an eben diesem Tage führe ich eure Scharen aus Ägypterland. Haltet diesen Tag in eueren Geschlechtern als ewige Einrichtung!',
        18: 'Am vierzehnten des ersten Monds am Abend esset ungesäuertes Brot bis zu dem Abend des einundzwanzigsten des Monats!',
        19: "Kein Sauerteig finde sich sieben Tage lang in euren Häusern: Wer Gesäuertes ißt, werde aus Israels Gemeinschaft gestrichen! Sei's Fremdling, sei's Einheimischer!",
        20: 'Nicht einen Bissen gesäuertes Brot sollt ihr essen! In all euren Siedlungen eßt nur ungesäuertes Brot!"',
        21: 'Dann berief Moses alle Ältesten Israels und sprach zu ihnen: "Zieht aus und holt für eure Sippen Schafe und schlachtet das Passah!',
        22: 'Dann nehmt ein Ysopbüschel, taucht es in das Blut im Becken und streicht von dem Blute im Becken an den Türsturz und an die beiden Türpfosten! Euer keiner soll bis zum Morgen aus der Tür seines Hauses gehen!',
        23: 'Zieht dann der Herr hindurch, das Ägypterland zu schlagen, und sieht er an dem Türsturz und an den beiden Türpfosten das Blut und übergeht der Herr die Tür, dann läßt er den Verderber nicht eure Häuser zum Schlagen betreten.',
        24: 'Achtet doch dies Wort! Als Satzung für euch und eure Kinder gelte es auf ewige Zeiten!',
        25: 'Und kommt ihr in das Land, das der Herr euch gibt, wie er verheißen, dann haltet diesen Brauch!',
        26: "Und fragen eure Söhne euch: 'Was ist dieser Brauch!',",
        27: 'dann saget: \'Das ist das Passahopfer für den Herrn, der Israels Häuser im Ägypterland übergangen, als er Ägypten schlug; unsere Häuser aber hat er ausgenommen.\'" Da neigte sich das Volk und warf sich nieder.',
        28: 'Dann gingen die Israeliten hin und taten so. Wie der Herr Moses und Aaron geboten, so taten sie auch hernach.',
        29: 'Da geschah es zur Mitternacht, daß der Herr alle Erstgeburt im Ägypterlande schlug, von Pharaos Erstgeborenem an, der auf seinem Throne sitzen sollte, bis zum Erstgeborenen der Sklavin, die im Kerker lag, und alle Erstlingswürfe des Viehs.',
        30: 'Noch in der Nacht stand Pharao auf mit all seinen Dienern und ganz Ägypten, und ein großes Jammern war in Ägypten; denn kein Haus gab es, in dem nicht ein Toter lag.',
        31: 'Da berief er Moses und Aaron noch in der Nacht und sprach: "Auf! Fort aus meinem Volke, ihr und die Söhne Israels! Geht! Verehrt den Herrn nach euren Worten!',
        32: 'Nehmt auch eure Schafe und Rinder mit, wie ihr gesagt, und zieht fort! Doch segnet mich zuvor!"',
        33: 'Auch die Ägypter drängten darauf, das Volk schleunigst aus dem Land zu bringen; denn sie sagten: "Wir sind sonst alle des Todes."',
        34: 'Da nahm das Volk seinen Brotteig, bevor er noch durchsäuert war, und seine Backschüsseln, in seine Mäntel gewickelt, auf die Schulter.',
        35: 'Die Israeliten aber hatten nach Mosis Worten getan, und so erbaten sie sich von den Ägyptern Silber- und Goldschmuck und Kleider.',
        36: 'Der Herr aber hatte die Ägypter dem Volke günstig gestimmt. Und er ließ sie bitten, und sie gewannen sich die Ägypter.',
        37: 'Die Israeliten brachen von Ramses auf, nach Sukkot zu, ungefähr 600.000 Fußgänger, ohne Kinder.',
        38: 'Auch viel Mischvolk zog mit ihnen, dazu Schafe und Rinder, eine mächtig große Herde.',
        39: 'Sie buken ungesäuerte Brotkuchen aus dem Teige, den sie aus Ägypten mitnahmen; denn er war nicht gesäuert. Sie wurden ja von den Ägyptern verjagt. So konnten sie sich nicht aufhalten und keine Zehrung bereiten.',
        40: 'Der Israeliten Bleiben in Ägypten betrug 430 Jahre.',
        41: 'Nach Ablauf der 430 Jahre geschah es, daß genau am selben Tage alle Scharen des Herrn aus Ägypten zogen.',
        42: 'Eine durchwachte Nacht war das für den Herrn, als er sie aus dem Land Ägypten führte. Dies ist die Nacht, da alle Israeliten zu Ehren des Herrn in jedem Geschlecht Nachtwachen halten.',
        43: 'Und der Herr sprach zu Moses und Aaron: "Das ist die Passahordnung: Kein Sohn der Fremde darf mitessen.',
        44: 'Aber jeder um Geld gekaufte Sklave darf mitessen, wenn du ihn beschnitten hast.',
        45: 'Beisaß und Mietling dürfen nicht mitessen.',
        46: 'Im Hause allein soll es gegessen werden. Aus dem Hause darfst du nichts vom Fleisch auf die Straße bringen. Auch kein Bein dürft ihr daran abbrechen.',
        47: 'Die ganze Gemeinde Israels soll es so halten!',
        48: 'Ist ein Gast bei dir und will dem Herrn Passah feiern, so muß alles Männliche bei ihm beschnitten sein. Dann erhält er das Vorrecht, es zu feiern. Er sei dann wie ein Sproß des Landes! Kein Unbeschnittener aber darf davon essen.',
        49: 'Ein gleich Gesetz gilt für den Eingeborenen wie für den Gast, der bei euch weilt."',
        50: 'Da taten alle Israeliten so. Wie der Herr dem Moses und Aaron befohlen, so taten sie.',
        51: 'An eben jenem Tage führte der Herr die Israeliten aus dem Ägypterland, nach ihren Scharen geordnet, heraus.',
    },
    13: {
        1: 'Da sprach der Herr zu Moses also:',
        2: '"Weihe mir alles Erstgeborene! Was bei den Israeliten den Mutterschoß durchbricht, ist mein, Mensch und Vieh."',
        3: 'Und Moses sprach zum Volke: "Feiert zum Gedächtnis diesen Tag, da ihr aus Ägypten, aus dem Sklavenhause, gezogen seid! Mit starker Hand hat euch der Herr von dannen geführt. Also werde nichts Gesäuertes gegessen!',
        4: 'Heute ziehet aus, am Neumond des Abib!',
        5: 'Bringt dich der Herr in das Land der Kanaaniter, Chittiter, Amoriter, Chiwiter und Jebusiter, er, der einst deinen Vätern zugeschworen, ein Land, von Milch und Honig fließend, dir zu geben, dann übe diesen Brauch an diesem Neumond!',
        6: 'Sieben Tage sollst du ungesäuertes Brot essen! Am siebten Tage aber sei ein Fest des Herrn!',
        7: 'Ungesäuertes Brot werde die sieben Tage gegessen! Nichts Gesäuertes sei bei dir zu sehen! Kein Sauerteig sei bei dir in deinem ganzen Ortsgebiete zu sehen!',
        8: "Aber deinem Sohne vermelde an diesem Tage also: 'Um dessentwillen, was der Herr mir getan beim Auszug aus Ägypten, geschieht dies.'",
        9: 'Und es sei dir zum Zeichen an der Hand und zum Merkmal zwischen den Augen, damit in deinem Munde sei die Lehre über den Herrn, daß dich der Herr mit starker Hand aus Ägypten geführt!',
        10: 'Und achte diese Satzung zu ihrer Zeit, Jahr für Jahr!',
        11: 'Bringt dich der Herr ins Kanaaniterland, wie er dir zugeschworen und deinen Vätern, und gibt er es dir,',
        12: 'dann tritt dem Herrn alles ab, was den Mutterschoß durchbricht! Jeder Erstlingswurf des Viehes, das du hast, falls er männlich ist, gehört dem Herrn.',
        13: 'Doch jeden Erstlingswurf des Esels sollst du mit einem Schafe auslösen und willst du nicht, dann zerbrich ihm das Genick! Bei deinen Kindern aber mußt du jede männliche Erstgeburt auslösen.',
        14: "Und fragt dich dein Sohn einmal: 'Was ist das?' dann sprich zu ihm: 'Mit starker Hand hat uns der Herr aus Ägypten geführt, aus dem Frönerhause.",
        15: 'Als Pharao sich weigerte, uns freizulassen, tötete der Herr im Lande Ägypten jede Erstgeburt, vom Erstgeborenen des Menschen bis zum Erstlingswurf des Viehs. Darum opfere ich dem Herrn jeden männlichen Erstlingswurf und löse jeden Erstgeborenen meiner Söhne aus.',
        16: 'Und dir sei es zum Zeichen an der Hand und zur Marke zwischen den Augen, daß uns der Herr mit starker Hand aus Ägypten geführt hat!\'"',
        17: 'Als Pharao das Volk entließ, führte es Gott nicht den Weg nach dem Philisterland, der doch der nächste war. Denn Gott sprach: "Daß es nicht das Volk gereue, wenn es Kämpfe sähe, und dann nach Ägypten wieder wollte!"',
        18: 'So ließ Gott das Volk auf dem Wege zur Wüste am Schilfmeer einschwenken. Die Israeliten aber zogen geordnet aus dem Ägypterland fort.',
        19: 'Und Moses nahm Josephs Gebeine mit sich. Denn dieser hatte die Israeliten eidlich beschworen: "Bedenkt euch einstens Gott, dann nehmt meine Gebeine mit euch!"',
        20: 'Und sie zogen von Sukkot ab und lagerten sich in Etam am Rand der Wüste.',
        21: 'Der Herr aber zog vor ihnen einher, des Tags in einer Wolkensäule, sie den Weg zu leiten, und des Nachts in einer Feuersäule, ihnen zu leuchten, so daß sie Tag und Nacht wandern konnten.',
        22: 'Nicht wich vor dem Volke die Wolkensäule bei Tag und die Feuersäule nicht bei Nacht.',
    },
    14: {
        1: 'Und der Herr sprach zu Moses:',
        2: '"Befiehl den Söhnen Israels, daß sie umkehren und sich vor Pihachirot lagern, zwischen Migdol und dem Meere vor Baalsephon. Ihm gegenüber sollt ihr am Meere lagern!',
        3: "Dann sagt Pharao von den Israeliten: 'Verirrt haben sie sich im Land. Die Wüste hält sie umschlossen.'",
        4: 'Und ich verhärte Pharaos Herz, daß er sie verfolge. So räche ich mich an Pharao und all seiner Heeresmacht. Die Ägypter sollen dann wissen, daß ich der Herr bin." Und sie taten so.',
        5: 'Da ward es Ägyptens König klar, daß das Volk entwichen sei. Und Pharaos wie seiner Diener Herz ward anders gegen das Volk, und sie sprachen: "Was haben wir da gemacht, daß wir Israel aus unserem Dienst entlassen haben?"',
        6: 'Und er schirrte seinen Wagen und nahm sein Volk mit sich.',
        7: 'Sechshundert erlesene Wagen nahm er mit und was sonst an Wagen in Ägypten war, auf ihnen allen Streiter.',
        8: 'Und der Herr verhärtete Pharaos, des Ägypterkönigs, Herz, und so verfolgte er die Israeliten. Die Israeliten aber waren in dichter Schar ausgezogen.',
        9: 'So setzten ihnen die Ägypter nach und erreichten sie in dem Lager am Meer, mit allen Rossen der Wagen Pharaos, mit seinen Reitern und dem übrigen Heere, bei Pihachirot vor Baalsephon.',
        10: 'Wie nun Pharao nähergekommen war, erhoben die Israeliten die Augen. Da waren ihnen die Ägypter nachgezogen, und so erschraken sie heftig. Da schrien die Israeliten zum Herrn.',
        11: 'Und sie sprachen zu Moses: "Fehlte es an Gräbern in Ägypten, daß du uns zum Sterben in der Wüste mitgenommen hast? Was hast du uns da getan, uns aus Ägypten zu führen?',
        12: 'Ist es nicht das gewesen, was wir zu dir in Ägypten gesagt: \'Laß uns in Ruhe! Wir wollen den Ägyptern dienen.\' Ja, besser wäre es für uns, den Ägyptern zu dienen, als in der Wüste zu sterben."',
        13: 'Da sprach Moses zum Volke: "Fürchtet euch nicht! Haltet stand! Dann erlebt ihr des Herrn Hilfe, die er euch heute schaffen wird. Denn so, wie ihr heute die Ägypter seht, seht ihr sie in alle Ewigkeit nicht wieder.',
        14: 'Der Herr wird für euch streiten, und ihr dürft ruhig zusehen."',
        15: 'Und der Herr sprach zu Moses: "Was schreist du zu mir? Heiße die Söhne Israels aufbrechen!',
        16: 'Du aber heb deinen Stab empor, streck die Hand übers Meer und spalte es! Mitten durchs Meer sollen die Israeliten auf dem Trockenen ziehen.',
        17: 'Ich aber verhärte der Ägypter Sinn. Sie sollen ihnen nachziehen. Ich räche mich so an Pharao und seiner ganzen Kriegermacht, an seinen Wagen und Reitern.',
        18: 'Die Ägypter sollen dann erkennen, daß ich der Herr bin, wenn ich mich räche an Pharao und seinen Wagen und Reitern."',
        19: 'Gottes Engel aber, der vor Israels Heer einherzog, erhob sich und trat hinter sie. Auch die Wolkensäule vor ihnen zog weg und stand hinter ihnen.',
        20: 'So kam sie zwischen das ägyptische und das israelitische Lager. Da war nun die Wolke und die Finsternis da, und sie vermehrte die Nacht, so daß keines dem anderen während der ganzen Nacht zu nahe kam.',
        21: 'Dann streckte Moses seine Hand über das Meer. Und der Herr trieb das Meer zurück durch einen starken Ostwind während der ganzen Nacht und machte das Meer zum Sandgrund. Und das Wasser ward geteilt.',
        22: 'Die Israeliten gingen nun mitten durch das Meer im Trockenen. Und die Wasser standen als Mauer zu ihrer Rechten und Linken.',
        23: 'Aber die Ägypter setzten nach und gingen hinter ihnen mit allen Rossen Pharaos, seinen Wagen und Reitern, mitten in das Meer hinein.',
        24: 'In der Morgenwache geschah es; da neigte sich der Herr in der Feuer- und Wolkensäule über den Zug der Ägypter und verwirrte den ägyptischen Zug.',
        25: 'Er hemmte ihre Wagenräder und ließ sie nur mit Beschwer vorwärts kommen. Da sprach Ägypten: "Fliehen will ich vor Israel." Denn der Herr stritt für sie gegen Ägypten.',
        26: 'Da sprach der Herr zu Moses: "Streck deine Hand über das Meer! Zurückfluten sollen die Wasser über die Ägypter, ihre Wagen und Reiter!"',
        27: 'Da streckte Moses seine Hand über das Meer. Und das Meer flutete um die Morgenwende zu seinem Boden zurück, indes die Ägypter ihm entgegenflohen. So trieb der Herr die Ägypter mitten in das Meer.',
        28: 'Zurückfluteten da die Wasser und bedeckten die Wagen und Reiter in Pharaos ganzem Heere, das ihnen nachgezogen war ins Meer. Nicht einer von ihnen blieb übrig.',
        29: 'Die Israeliten aber waren auf dem Trockenen mitten durch das Meer gezogen, und die Wasser standen als Mauer zu ihrer Rechten und Linken.',
        30: 'So befreite der Herr an jenem Tage Israel aus der Hand Ägyptens, und Israel sah die Ägypter tot am Ufer des Meeres.',
        31: 'Da sah Israel die Großtat, die der Herr an Ägypten getan. Und das Volk fürchtete den Herrn und vertraute dem Herrn und seinem Diener Moses.',
    },
    15: {
        1: 'Damals sang Moses mit den Israeliten dieses Lied dem Herrn. Sie sprachen also: "Dem Herrn will ich lobsingen. Er hat gesiegt, ins Meer gestürzt das Roß und seinen Reiter.',
        2: 'Dem Herrn mein Lobgesang! Zur Rettung ward er mir. So ist mein Gott; ihn preise ich. Ich rühme meines Vaters Gott.',
        3: 'Der Herr ein Kriegsheld, sein Name Herr.',
        4: 'Die Wagen Pharaos und seine Mannen hat er ins Meer geworfen. Ins Schilfmeer tauchten die besten seiner Streiter.',
        5: 'Abgründe deckten sie; sie fuhren in die Strudel wie ein Stein.',
        6: 'Herr, Deine Rechte, an Kraft so herrlich, Herr, Deine Rechte zerschmettert Feinde.',
        7: 'Mit Deines Zornes Fülle zerschlägst Du Deine Gegner; ausschickst Du Deinen Grimm, er frißt sie wie das Stroh.',
        8: 'Durch Deines Zornes Hauch schwoll an das Wasser. Wallgleich die Fluten standen, und Abgründe gerannen in Meeres Herzen.',
        9: "Es sprach der Feind: 'Ich jage nach und hole ein und teile Raub. An ihnen meine Gier sich letze! Mein Schwert zück ich. Sie tilge meine Hand!'",
        10: 'Du bliesest nur mit Deinem Hauche; schon bedeckte sie das Meer. Sie wirbelten wie Blei in die gewaltigen Gewässer.',
        11: 'Wer gleicht Dir bei den Göttern, Herr? Wer gleicht Dir, Du Erhabener im Heiligtum, Furchtbarer, Schrecklicher, Du Wunderwirker?',
        12: 'Du streckst die Rechte aus, und sie verschluckt die Erde.',
        13: 'Du lenkst mit Deiner Huld das Volk, das Du erlöst. Du leitest es in Deiner Kraft zu Deiner heiligen Wohnstatt hin.',
        14: "Die Völker hören's, zittern, und Angst packt die Bewohner Philistäas.",
        15: 'Zusammenschrecken Edoms Fürsten, und Moabs Edelinge faßt Erbeben, und Kanaans Insassen alle zagen.',
        16: 'Entsetzen, Schrecken stürzt auf sie; ob Deines Armes Größe erstarren sie zu Stein, bis daß hindurchzieht, Herr, Dein Volk, bis daß hindurchzieht dies Dein Volk, das Du erkauft.',
        17: 'Herbei bringst Du sie selbst und pflanzest sie an jener Stätte ein, die Du zu Deinem Sitze, Herr, bereitet, im Heiligtum, mein Herr, das Deine Hände selbst erstellt.',
        18: 'Der Herr ist König immerdar und ewig." -',
        19: 'Pharaos Rosse waren ja samt seinen Wagen und Reitern ins Meer geraten, und der Herr brachte über sie des Meeres Gewässer zurück. Die Israeliten aber waren im Trockenen mitten durchs Meer gezogen.',
        20: 'Da nahm die Prophetin Mirjam, Aarons Schwester, die Pauke zur Hand, und alle Frauen folgten ihr mit Pauken und Reigentänzen.',
        21: 'Da sang ihnen Mirjam zu: "Lobsingt dem Herrn! Er ist so hoch und hehr, der Rosse und Reiter gestürzt ins Meer."',
        22: 'Moses ließ nun Israel vom Schilfmeer aufbrechen. Sie zogen in die Wüste Sur hinein. Drei Tage gingen sie durch die Wüste; sie fanden aber kein Wasser.',
        23: 'So kamen sie nach Mara; aber sie konnten in Mara kein Wasser trinken, weil es bitter war; daher hieß es Mara.',
        24: 'Da murrte das Volk gegen Moses und sprach: "Was sollen wir trinken?"',
        25: 'Er aber rief zum Herrn. Und der Herr wies ihn auf einen Baum. Davon warf er ins Wasser, und das Wasser ward süß. Dort gab er ihm Gesetz und Recht, und dort prüfte er es.',
        26: 'Er sprach: "Hörst du gehorsam auf die Stimme des Herrn, deines Gottes, und tust, was recht ist vor ihm, dann horchst du auf seine Weisungen und hältst all seine Satzungen, dann lege ich dir keines der Leiden auf, die ich Ägypten auferlegt. Ich, der Herr, bin dein Arzt."',
        27: 'Und sie kamen nach Elim. Dort waren zwölf Quellen und siebzig Palmen. Und sie lagerten dort am Wasser.',
    },
    16: {
        1: 'Von Elim brachen sie auf und kamen, die ganze Gemeinschaft Israels, in die Wüste Sin zwischen Elim und Sinai am fünfzehnten Tage des zweiten Monats nach ihrem Auszuge aus Ägypterland.',
        2: 'Da murrten sie, die ganze israelitische Gemeinschaft, gegen Moses und Aaron wegen der Wüste.',
        3: 'Und die Israeliten sprachen zu ihm: "Wären wir doch im Ägypterland durch des Herrn Hand gestorben! Da saßen wir beim Fleischtopf und aßen uns satt an Brot. Ihr habt uns in diese Wüste geführt, diese ganze Gemeinde durch Hunger zu töten."',
        4: 'Da sprach der Herr zu Moses: "Ich lasse euch nun Brot vom Himmel regnen. Das Volk gehe hinaus! Doch lese es jeden Tag nur den Tagesbedarf! Damit prüfe ich es, ob es meiner Weisung folgt oder nicht.',
        5: 'Messen sie dann am sechsten Tage, was sie einbringen, so wird es das Doppelte sein von dem, was sie tagtäglich lesen."',
        6: 'Da sprachen Moses und Aaron zu allen Israeliten: "Am Abend erkennt ihr, daß der Herr euch aus Ägypterland geführt hat.',
        7: 'Und am Morgen schaut ihr des Herrn Majestät, hat er doch euer Gemurr gegen den Herrn vernommen. Was sind wir, daß ihr gegen uns murrt?"',
        8: 'Und Moses sprach: "Der Herr gibt euch am Abend Fleisch zu essen und zur Genüge Brot am Morgen, hat doch der Herr euer Gemurr wider ihn vernommen. Was sind wir? Nicht gegen uns geht euer Gemurr, sondern gegen den Herrn!"',
        9: 'Und Moses sprach zu Aaron: "Sag der ganzen Gemeinschaft der Söhne Israels: \'Tritt vor den Herrn! Er hat euer Gemurr vernommen.\'"',
        10: 'Als Aaron dies der ganzen Gemeinschaft der Israeliten verkündigte und sie sich der Wüste zuwandten, da erschien des Herrn Majestät in der Wolke.',
        11: 'Und der Herr sprach zu Moses also:',
        12: '"Der Israeliten Gemurr habe ich vernommen. Sag ihnen dies: Ihr werdet Fleisch am Abend essen und morgen früh euch am Brote sättigen. Da möget ihr erkennen, daß ich der Herr, euer Gott, bin."',
        13: "Und Abend war's, da zog ein Wachtelschwarm heran und bedeckte das Lager. Und am Morgen lag eine Tauschicht rings um das Lager.",
        14: 'Dann stieg die Tauschicht auf, und auf der Wüstenfläche lag etwas Dünnes, Schuppiges, fein wie der Reif auf der Erde.',
        15: 'Die Israeliten sahen es und sprachen zueinander: "Was ist das?", denn sie wußten nicht, was es war. Da sprach Moses zu ihnen: "Dies ist das Brot, das euch der Herr zu essen gibt.',
        16: 'Das ist es, was der Herr mir geboten: \'Leset davon auf, jeder nach Bedarf. Je ein Maß auf den Kopf nach eurer Seelenzahl hole jeglicher für die in seinem Zelt!\'"',
        17: 'Und die Israeliten taten so. Sie lasen auf, der eine viel, der andere wenig.',
        18: 'Da maßen sie mit dem Maß. Wer viel geholt, hatte nicht mehr, wer wenig geholt, nicht weniger gehabt. Jeder hatte für seinen Bedarf gelesen.',
        19: 'Und Moses sprach zu ihnen: "Niemand hebe davon bis zum Morgen auf!"',
        20: 'Aber sie hörten nicht auf Moses; sondern einige Männer hoben davon bis zum Morgen auf. Da ward es voller Würmer und roch übel. Moses aber ward auf sie zornig.',
        21: 'So lasen sie es Morgen für Morgen auf, jeder nach seinem Bedarf. Wenn aber die Sonne heiß brannte, schmolz es.',
        22: 'Aber am sechsten Tage lasen sie doppelte Speise, zwei Maß für einen. Da kamen alle Fürsten der Gemeinschaft und meldeten es Moses.',
        23: 'Er sprach zu ihnen: "Dies ist es, was der Herr gemeint: Der heilige Ruhetag des Herrn ist morgen. Was ihr backen wollt, backet jetzt! Kochet jetzt, was ihr kochen wollt! Was übrigbleibt, verwahrt bis zum Morgen!"',
        24: 'Und sie legten es bis zum anderen Morgen zurück, wie Moses befohlen. Nichts roch übel, und kein Wurm war darin.',
        25: 'Und Moses sprach: "Eßt es heute! Denn heute ist ein Ruhetag des Herrn. Ihr findet nichts auf dem Felde.',
        26: 'Sechs Tage könnt ihr es sammeln. Aber am siebten Tage ist Sabbat; an dem gibt es nichts."',
        27: 'Doch am siebten Tage gingen vom Volke etliche zum Lesen hinaus; sie fanden aber nichts.',
        28: 'Da sprach der Herr zu Moses: "Wie lange wollt ihr meine Vorschriften und Gebote nicht halten?',
        29: 'Seht! Der Herr hat euch den Sabbat gegeben. Darum gibt er euch am sechsten Tag Speise für zwei Tage. So bleibe jeder daheim! Am siebten Tage aber gehe niemand von seinem Platz!"',
        30: 'So ruhte am siebten Tage das Volk.',
        31: 'Das Haus Israel aber nannte es Manna. Es war wie Koriandersamen, weißlich, und sein Geschmack wie Honigkuchen.',
        32: 'Und Moses sprach: "Das ist es, was der Herr geboten: \'Füllt ein Maß davon zum Verwahr für eure Geschlechter, damit sie sehen das Brot, mit dem ich in der Wüste euch gespeist, als ich euch aus Ägypterland geführt!\'"',
        33: 'Und Moses sprach zu Aaron: "Nimm einen Krug und tu ein ganzes Maß Manna hinein und lege ihn nieder vor dem Herrn zum Verwahr für eure Geschlechter!"',
        34: 'Und wie der Herr dem Moses befohlen, so legte ihn Aaron vor der Gesetzeslade nieder zum Verwahr.',
        35: 'Die Israeliten aber aßen das Manna vierzig Jahre, bis sie in bewohntes Land kamen. Das Manna aßen sie, bis sie an die Grenze des Landes kamen.',
        36: 'Ein Maß aber ist das Zehntteil eines Scheffels.',
    },
    17: {
        1: 'Sie nun, die ganze Gemeinschaft der Israeliten, zogen von der Wüste Sin weiter, in Tagesmärschen nach des Herrn Befehl. Sie lagerten zu Raphidim. Da war aber kein Trinkwasser für das Volk.',
        2: 'Das Volk aber haderte mit Moses und sprach: "Gebt uns Wasser zum Trinken!" Und Moses sprach zu ihnen: "Weshalb zankt ihr mit mir? Was prüft ihr den Herrn?"',
        3: 'Das Volk aber dürstete dort nach Wasser. Und so murrte das Volk gegen Moses und sprach: "Wozu hast du uns aus Ägypten geführt? Mich, meine Kinder und mein Vieh durch Durst zu töten?"',
        4: 'Da rief Moses zum Herrn und sprach: "Was fange ich mit diesem Volk noch an? Nur wenig, und sie steinigen mich."',
        5: 'Der Herr sprach zu Moses: "Übergehe das Volk und nimm dir von den Ältesten in Israel nur ein paar mit! Auch deinen Stab, mit dem du den Nil geschlagen, nimm mit und geh!',
        6: 'Siehe! Ich stehe dort vor dir auf dem Felsen am Horeb. Schlägst du an den Felsen, so fließt Wasser heraus, und das Volk kann trinken." Und Moses tat so vor den Augen der Ältesten Israels.',
        7: 'Und er nannte die Stätte Massa und Meriba, weil die Israeliten gezankt und den Herrn versucht hatten mit den Worten: "Ist der Herr unter uns oder nicht?"',
        8: 'Da kam Amalek und wollte mit Israel zu Raphidim kämpfen.',
        9: 'Und Moses sprach zu Josue: "Wähle uns Männer! Alsdann ziehe aus und kämpfe mit Amalek! Ich aber stelle mich morgen auf des Hügels Spitze, den Gottesstab in der Hand."',
        10: 'Und Josue tat, wie ihm Moses gesagt, bei dem Kampfe mit Amalek. Moses aber, Aaron und Hur waren auf den Gipfel des Hügels gestiegen.',
        11: 'Wie nun Moses seinen Arm erhob, siegte Israel, und wie er seinen Arm sinken ließ, siegte Amalek.',
        12: 'Aber Mosis Arme wurden steif. So nahmen sie einen Stein und legten ihm diesen unter, und er setzte sich darauf. Aaron aber und Hur stützten seine Arme, der eine hier, der andere dort. So blieben seine Arme fest bis zum Sonnenuntergang.',
        13: 'So überwand Josue Amalek und sein Volk mit des Schwertes Schärfe.',
        14: 'Da sprach der Herr zu Moses: "Schreibe dies zum Gedächtnis ins Buch und schärfe es Josue ein: \'Wegwischen will ich Amaleks Gedenken unterm Himmel!\'"',
        15: 'Und Moses erbaute einen Altar und nannte ihn "Mein Banner ist der Herr."',
        16: 'Er',
    },
    18: {
        1: 'Midians Priester Jetro aber, Mosis Schwiegervater, hörte alles, was Gott an Moses und seinem Volk Israel gewirkt, daß der Herr Israel aus Ägypten geführt hatte.',
        2: 'Da nahm Jetro, Mosis Schwiegervater, die Sippora, Mosis Weib, das er heimgeschickt hatte,',
        3: 'und ihre beiden Söhne. Der eine hieß Gersom, weil er gesagt: "Ich ward in fremdem Lande Fremdling."',
        4: 'Der andere hieß: Eliezer. Denn: "Meines Vaters Gott war meine Hilfe, und er befreite mich vor Pharaos Schwert".',
        5: 'So kam Mosis Schwiegervater Jetro mit seinen Söhnen und seinem Weibe zu Moses in die Wüste; er aber lagerte am Gottesberge.',
        6: 'Da ließ er Moses sagen: "Ich, Jetro, dein Schwiegervater, komme zu dir mit deinem Weibe und ihren beiden Söhnen."',
        7: 'Da ging Moses seinem Schwiegervater entgegen, neigte sich und küßte ihn. Dann fragten sie einander nach dem Befinden. Hierauf gingen sie in das Zelt.',
        8: 'Da erzählte Moses seinem Schwiegervater alles, was der Herr an Pharao und Ägypten getan um Israels willen, alles Ungemach, das sie unterwegs getroffen, und wie sie der Herr gerettet hatte.',
        9: 'Und Jetro freute sich all des Guten, das der Herr an Israel getan, als er es aus Ägyptens Gewalt erlöst.',
        10: 'Und Jetro sprach: "Gepriesen sei der Herr, der euch befreit aus Ägyptens und Pharaos Hand und der das Volk aus Ägyptens Hand befreit hat!',
        11: 'Nun sehe ich, daß der Herr größer ist als alle Götter; denn merkwürdig ist es, wie man sie verspottet hat."',
        12: 'Dann weihte Mosis Schwiegervater Jetro Gott Brand- und Schlachtopfer. Und Aaron kam mit allen Ältesten Israels, mit Mosis Schwiegervater ein Mahl vor Gott zu halten.',
        13: 'Am anderen Morgen setzte sich Moses, das Volk zu richten, und das Volk stand vor Moses vom Morgen bis zum Abend.',
        14: 'Als Mosis Schwiegervater sah, wieviel er dem Volke tat, sprach er: "Was ist das, wie du es mit dem Volke machst? Warum sitzest du allein, und alles Volk steht vom Morgen bis zum Abend vor dir?"',
        15: 'Da sprach Moses zu seinem Schwiegervater: "Das Volk kommt zu mir, Gott zu fragen.',
        16: 'Haben sie eine Rechtssache, so kommt sie vor mich, und ich richte zwischen ihnen und künde Gottes Rechtssprüche und seine Weisungen."',
        17: 'Da sprach Mosis Schwiegervater zu ihm: "Nicht gut ist\'s, wie du es treibst.',
        18: 'Du reibst dich auf und das Volk bei dir. Es ist zu schwer für dich. Du kannst es allein nicht machen.',
        19: 'Hör auf mich! Ich rate dir, und Gott sei mit dir! Vertritt du das Volk gegenüber Gott! Und bring du die Sachen vor Gott!',
        20: 'Erkläre ihnen die Gesetze und Weisungen! Zeig ihnen den Weg, den sie gehen, und das Werk, das sie tun sollen!',
        21: 'Aber du selbst sollst dir aus dem ganzen Volke Männer ersehen, tüchtig, gottesfürchtig, Männer, vertrauenswürdig, vorteilhassend! Setze sie über sie als Führer von Tausendschaften, Hundertschaften, Fünfzigschaften und Zehnschaften!',
        22: 'Sie sollen jederzeit das Volk richten! Alle wichtigen Sachen sollen sie vor dich bringen! Die geringeren aber sollen sie alle selber entscheiden! Entlaste dich und laß sie mit dir tragen!',
        23: 'Tust du so, dann kannst du bestehen bei dem, was Gott dir befiehlt. Und dies ganze Volk geht befriedigt heim."',
        24: 'Und Moses hörte auf seines Schwiegervaters Rat und tat ganz so, wie er gesagt hatte.',
        25: 'Moses wählte aus ganz Israel tüchtige Männer aus und stellte sie an die Spitze des Volkes, als Führer von Tausendschaften, Hundertschaften, Fünfzigschaften und Zehnschaften.',
        26: 'Sie sprachen dem Volke jederzeit Recht. Die schwierigen Sachen aber brachten sie vor Moses; die geringfügigen entschieden sie alle selbst.',
        27: 'Dann ließ Moses seinen Schwiegervater heimziehen, und er ging heim in sein Land.',
    },
    19: {
        1: 'Am dritten Neumond nach dem Auszug der Israeliten aus Ägypten, genau auf den Tag, waren sie in die Wüste Sinai gekommen.',
        2: 'Sie brachen nämlich von Raphidim auf und kamen so in die Wüste Sinai. Und sie lagerten sich in der Wüste. Und Israel lagerte dort gegenüber dem Berge.',
        3: 'Moses aber stieg zu Gott hinauf. Da rief ihm der Herr vom Berge zu: "Sprich also zu dem Jakobshaus und kündige den Söhnen Israels:',
        4: "'Ihr selber habt gesehen, was ich an Ägypten getan und wie ich euch auf Adlerflügeln trug und euch zu mir herbrachte.",
        5: 'Nun sollt ihr auf meine Stimme hören: Haltet ihr meinen Bund, dann seid ihr mir aus allen Völkern ein Sondergut. Denn mein ist die ganze Erde.',
        6: 'Ihr aber sollt mir sein ein Königreich von Priestern, ein heilig Volk.\' Das sind die Worte, die du den Israeliten sagen sollst."',
        7: 'Da kam Moses, berief des Volkes Ältesten und trug ihnen alle diese Worte vor, die der Herr ihm aufgetragen.',
        8: 'Und das ganze Volk erwiderte einhellig und sprach: "Alles, was der Herr befiehlt, wollen wir tun." Und Moses überbrachte die Worte des Volkes dem Herrn.',
        9: 'Da sprach der Herr zu Moses: "Ich komme zu dir in dichter Wolke, damit das Volk höre, wenn ich mit dir rede, und daß sie für immer auch dir vertrauen." Moses aber berichtete die Worte des Volkes dem Herrn.',
        10: 'Und der Herr sprach zu Moses: "Geh zum Volk! Bereite es vor, heute und morgen! Sie sollen saubere Kleider tragen!',
        11: 'Für übermorgen seien sie bereit! Denn übermorgen fährt der Herr vor des ganzen Volkes Augen nieder auf den Sinaiberg.',
        12: "Das Volk aber schranke du ringsum ein und sprich: 'Hütet euch, auf den Berg zu steigen oder nur an seinen Fuß zu rühren! Wer den Berg berührt, erleidet Todesstrafe.'",
        13: 'Nicht soll eine Hand an ihn rühren! Gesteinigt oder durchstochen werde, ob Vieh oder Mensch! Nicht dürfen sie am Leben bleiben. Erst wenn das Lärmhorn tönt, dürfen sie den Berg hinaufsteigen."',
        14: 'Da stieg Moses von dem Berge zum Volke hinab und bereitete das Volk vor. Sie legten saubere Gewänder an.',
        15: 'Dann sprach er zum Volke: "Für übermorgen haltet euch bereit! Berührt kein Weib!"',
        16: 'Als es am dritten Tage Morgen ward, brachen Donner los und Blitze. Eine schwere Wolke hing auf dem Berge, und mächtiger Hörnerschall ertönte. Da bebte alles Volk im Lager.',
        17: 'Dann führte Moses das Volk Gott entgegen aus dem Lager, und am Fuße des Berges stellte es sich auf.',
        18: 'Der ganze Berg Sinai aber rauchte, weil der Herr auf ihn im Feuer niedergefahren war. Und sein Rauch stieg auf, wie des Schmelzofens Rauch. Und der ganze Berg erbebte heftig.',
        19: 'Der Hörnerschall aber ward immer stärker. Und Moses redete; die Gottheit aber antwortete ihm nur in einem Schall.',
        20: 'Der Herr fuhr also auf den Berg Sinai, auf den Gipfel des Berges, nieder. Da berief der Herr den Moses auf den Gipfel des Berges, und Moses stieg hinan.',
        21: 'Und der Herr sprach zu Moses: "Steig hinab! Schärfe dem Volke ein, daß sie nicht vorwärtsdringen, den Herrn zu schauen! Sonst würden viele aus ihnen fallen.',
        22: 'Die Priester selbst, die sonst dem Herrn nahen dürfen, müssen stehenbleiben, daß der Herr nicht gegen sie losfahre."',
        23: 'Da sprach Moses zum Herrn: "Das Volk kann nicht den Sinaiberg besteigen; du hast ja selbst uns eingeschärft: \'Umschranke den Berg! Umhege ihn!\'"',
        24: 'Da sprach der Herr zu ihm: "Geh hinab und komm mit Aaron wieder! Aber die Priester und das Volk dürfen nicht stürmisch zum Herrn heraufsteigen, daß er nicht gegen sie losfahre."',
        25: 'Da stieg Moses zum Volke hinab und sprach mit ihm.',
    },
    20: {
        1: 'Und Gott redete all diese Worte; er sprach:',
        2: '"Ich bin der Herr, dein Gott, der dich aus dem Ägypterland, aus dem Frönerhaus geführt.',
        3: 'Du sollst keinen anderen Gott gleich mir haben!',
        4: 'Du sollst kein Bild dir machen, noch eine Abform dessen, was im Himmel droben ist oder auf Erden unten oder in dem unterirdischen Gewässer!',
        5: 'Du sollst dich nicht vor solchen niederwerfen und nimmer sie verehren! Ein eifersüchtiger Gott bin ich, der Herr, dein Gott, der da die Schuld der Väter heimsucht an den Kindern, Enkeln und Urenkeln derer, die mich hassen,',
        6: 'doch Huld erweist den Tausenden von denen, die mich lieben und die meine Gebote halten.',
        7: 'Du sollst nicht des Herrn, deines Gottes, Namen eitel nennen! Der Herr läßt den nicht ungestraft, der seinen Namen eitel nennt.',
        8: 'Gedenke, den Sabbattag zu heiligen!',
        9: 'Sechs Tage sollst du arbeiten und all dein Werk verrichten!',
        10: 'Ein Ruhetag, dem Herren, deinem Gott, zu Ehren, ist jedoch der siebte Tag. An ihm verrichte kein Geschäft, nicht du und nicht dein Sohn, noch deine Tochter, noch dein Knecht, noch deine Magd, und nicht dein Vieh und nicht dein Gast in deinen Toren!',
        11: 'Denn in sechs Tagen hat der Herr den Himmel und die Erde, das Meer und alles, was darin, gemacht. Am siebten Tage aber ruhte er. Deswegen hat der Herr den Ruhetag gesegnet, und also heiligte er ihn.',
        12: 'Ehre deinen Vater und deine Mutter, damit du lange lebest auf dem Erdboden, den dir der Herr, dein Gott, verleiht!',
        13: 'Du sollst nicht morden!',
        14: 'Du sollst nicht ehebrechen!',
        15: 'Du sollst nicht stehlen!',
        16: 'Du sollst nicht gegen deinen Nächsten falsches Zeugnis ablegen!',
        17: 'Du sollst nicht deines Nächsten Haus begehren! Du sollst nicht deines Nächsten Weib begehren, noch seinen Knecht, noch seine Magd, und nicht sein Rind, noch seinen Esel, nichts, was deines Nächsten ist!"',
        18: 'Und alles Volk ward inne der Donnerschläge, der Blitze, des Hörnerschalls und des rauchenden Berges. Und das Volk sah es, lief zurück und stand fern.',
        19: 'Dann sprachen sie zu Moses: "Rede du mit uns! Dann wollen wir zuhören. Aber nicht rede Gott mit uns! Sonst sterben wir."',
        20: 'Da sprach Moses zum Volke: "Habt keine Furcht! Die Gottheit ist gekommen, euch zu prüfen und damit die Furcht vor ihr in euch bleibe, auf daß ihr nicht sündiget."',
        21: 'So stand das Volk fern. Moses aber trat zu dem Wolkendunkel, in dem Gott war.',
        22: 'Da sprach der Herr zu Moses: "So sollst du sprechen zu den Israeliten: \'Ihr selber habt gesehen, daß ich mit euch vom Himmel aus geredet habe.',
        23: 'Ihr sollt mich nicht als einen Gott aus Silber oder Gold machen. Das dürft ihr euch nicht machen.',
        24: 'Du sollst aus Erde mir einen Altar anfertigen und darauf deine Brand- und Mahlopfer und deine Schafe und Rinder opfern. Wo immer meinen Namen ich ausspreche, da komme ich zu dir, und alsdann segne ich dich.',
        25: 'Machst du mir aber aus Steinen einen Altar, dann sollst du ihn nicht mit behauenen Steinen bauen! Denn du entweihest sie, schwingst du dein Eisen über sie.',
        26: 'Und nicht auf Stufen sollst du zu meinem Altar emporsteigen, damit nicht deine Blöße vor ihm offenbar werde!\'"',
    },
    21: {
        1: '"Dies sind die Rechtssatzungen, die du ihnen vorlegen sollst:',
        2: 'Kaufst du dir einen hebräischen Knecht, so diene er dir sechs Jahre! Im siebten aber gehe er frei und ledig aus!',
        3: 'Kam er mit seinem Bündel, so gehe er mit seinem Bündel; hatte er ein Weib, so gehe sein Weib mit ihm!',
        4: 'Gab ihm sein Herr ein Weib und gebar sie ihm Söhne oder Töchter, so bleibe das Weib mit seinen Kindern bei seinem Herrn. Er selber aber gehe mit seinem Bündel weg!',
        5: "Erklärt aber der Knecht: 'Ich liebe meinen Herrn, mein Weib und meine Kinder' und mag nicht frei weggehen,",
        6: 'dann bringe ihn sein Herr vor die Gottheit und stelle ihn an die Tür oder den Türpfosten! Und dann steche ihm sein Herr mit seinem Pfriemen durch das Ohr: Und nun sei er für immer sein Knecht!',
        7: 'Verkauft jemand seine Tochter als Magd, dann darf sie nicht wie Knechte fortgehen.',
        8: 'Mißfällt sie ihrem Herrn, der sie sich bestimmt hatte, dann lasse er sie loskaufen! Sie fremdem Volk zu verkaufen, hat er keine Macht, wenn er sie gehen läßt.',
        9: 'Bestimmt er sie aber seinem Sohne, dann tue er ihr nach der freien Mädchen Recht!',
        10: 'Nimmt er sich noch eine andere, dann schmälere er ihr nicht Fleisch, Kost, Gewand und Umarmung!',
        11: 'Tut er ihr von diesen dreien keines, dann gehe sie ohne Entgelt, umsonst weg!',
        12: 'Wer einen anderen totschlägt, soll des Todes sterben!',
        13: 'Hat er aber nicht aufgelauert, sondern Gott hat es seiner Hand widerfahren lassen, dann bestimme ich dir eine Stätte, wohin er fliehen kann.',
        14: 'Wenn aber jemand wider den Genossen brütet, ihn mit List zu töten, dann hole ihn von meinem Altar weg, daß er getötet werde!',
        15: 'Wer seinen Vater oder seine Mutter schlägt, soll des Todes sterben!',
        16: 'Wer einen Menschen raubt, er habe ihn verkauft oder er finde sich noch in seiner Hand, soll des Todes sterben!',
        17: 'Wer seinem Vater oder seiner Mutter flucht, soll des Todes sterben!',
        18: 'Wenn Männer streiten und einer schlägt den anderen so mit einem Steine oder mit der Faust, daß er zwar nicht stirbt, aber aufs Lager fällt,',
        19: 'so bleibe der Schläger frei, wenn er wieder aufsteht und im Freien an seiner Krücke umhergeht! Nur sein Feiernmüssen ersetze er und lasse ihn ausheilen!',
        20: 'Wenn jemand seinen Knecht oder seine Magd mit dem Stocke schlägt, und es stirbt eines unter seiner Hand, so werde es gesühnt!',
        21: 'Übersteht es aber noch einen oder zwei Tage, dann werde es nicht gesühnt; denn um sein eigen Geld geht es!',
        22: 'Wenn sich Männer raufen und stoßen ein schwangeres Weib, so daß es eine Fehlgeburt gibt, aber kein weiterer Schaden entsteht, so werde der Schuldige mit soviel bestraft, wie ihm der Gatte des Weibes auflegt! Er gebe es als Buße!',
        23: 'Entsteht jedoch ein Schaden, dann wende an: Leben um Leben,',
        24: 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß,',
        25: 'Brandmal um Brandmal, Wunde um Wunde, Beule um Beule!',
        26: 'Schlägt jemand seinem Knecht oder seiner Magd ins Auge und zerstört es, so lasse er ihn für sein Auge frei!',
        27: 'Schlägt er seinem Knecht oder seiner Magd einen Zahn aus, so lasse er ihn für seinen Zahn frei!',
        28: 'Und stößt ein Rind einen Mann oder ein Weib tot, so werde das Rind gesteinigt! Sein Fleisch werde nicht gegessen. Des Rindes Besitzer aber sei straffrei!',
        29: 'War aber das Rind lange zuvor stößig und war sein Besitzer schon verwarnt, er aber hütete es nicht und nun tötet es einen Mann oder ein Weib, so werde das Rind gesteinigt, und auch sein Besitzer soll des Todes sterben!',
        30: 'Wird ihm aber ein Sühnegeld auferlegt, so zahle er für sein Leben soviel Lösung, wie man ihm auflegt!',
        31: 'Gleichviel, ob es einen Sohn oder eine Tochter stößt, werde ihm dann nach diesem Recht getan!',
        32: 'Stößt aber das Rind einen Knecht oder eine Magd, dann zahle er ihrem Herrn dreißig Silberlinge! Das Rind aber werde gesteinigt',
        33: 'Läßt jemand einen Brunnen offen oder gräbt er einen Brunnen und überdeckt ihn nicht und fällt ein Rind oder Esel hinein,',
        34: 'dann zahle der Brunnenbesitzer! Den Geldwert erstatte er seinem Besitzer; das Tote aber sei sein!',
        35: 'Wenn jemandes Rind des anderen Rind totstößt, dann sollen sie das lebende Rind verkaufen und seinen Erlös teilen, und auch das tote sollen sie teilen!',
        36: 'Ist es aber bekannt gewesen, daß dieses Rind schon lange stößig war und sein Eigentümer behütete es nicht, so ersetze er das Rind durch ein anderes! Das tote aber sei sein! Wenn jemand ein Rind oder ein Schaf stiehlt und dann es schlachtet oder es verkauft, dann gebe er für das Rind fünf und für das Schaf vier andere!',
    },
    22: {
        1: 'Wird ein Dieb beim Einbruch ertappt und dann totgeschlagen, so entsteht seinetwegen keine Blutschuld.',
        2: 'Hat dabei aber schon die Sonne geschienen, dann ist seinethalben Blutschuld. Ersatz muß der Dieb leisten. Hat er nichts, dann werde er für seinen Diebstahl verkauft.',
        3: 'Wird bei ihm das Gestohlene, Rind, Esel oder Schaf noch lebend gefunden, dann leiste er nur doppelte Buße!',
        4: 'Läßt jemand ein Feld oder einen Weinberg abweiden und läßt er das Vieh laufen, daß es ein anderes Feld abweidet, dann gebe er zum Ersatz das Beste von seinem Feld und Weinberg!',
        5: 'Wenn Feuer auskommt und Gestrüpp ergreift und ein Getreidehaufen wird dabei verbrannt oder das Korn auf dem Halm oder das Feld, dann ersetze, wer den Brand entzündet hat!',
        6: 'Wenn jemand seinem Genossen Geld gibt oder Geräte zum Aufheben und dies ist aus dem Hause des Mannes gestohlen worden, dann ersetze der Dieb doppelt, falls er entdeckt wird!',
        7: 'Wird aber der Dieb nicht entdeckt, dann trete der Hausherr vor die Gottheit, wenn er sich nicht an des anderen Habe vergriffen hat!',
        8: "Bei Unterschlagung eines Rindes, eines Esels, eines Schafes, eines Mantels, bei allem, was abhanden gekommen und wovon man sagt: 'Das ist es', komme vor die Gottheit der beiden Sache! Wen Gott schuldig spricht, der ersetze dem anderen doppelt!",
        9: 'Wenn jemand einem anderen Esel oder Rinder oder Schafe oder sonst ein Tier zu hüten gibt und es stirbt oder wird verstümmelt oder verschleppt und keiner sieht es,',
        10: 'dann entscheidet zwischen beiden der Schwur beim Herrn, er habe nicht seine Hand an des anderen Habe gelegt. Das nehme der Besitzer an, und jener hat nichts zu ersetzen!',
        11: 'Ward es aber in seinem Beisein gestohlen, dann ersetze er dem Eigentümer!',
        12: 'Und wenn es zerrissen ward und er kann des zerrissenen Tieres Fell vorlegen, dann ersetze er nichts!',
        13: 'Wenn aber jemand eins vom anderen entlehnt und es wird verstümmelt oder stirbt, dann ersetze er, wenn sein Besitzer nicht zugegen war!',
        14: 'War aber der Besitzer da, dann ersetze er nichts! War es gemietet, bekommt er dafür den Mietpreis.',
        15: 'Betört jemand eine noch nicht verlobte Jungfrau und wohnt er ihr bei, dann mache er sie durch Morgengabe zum Weib!',
        16: 'Weigert sich aber ihr Vater, sie ihm zu geben, so zahle er nach der Brautgabe der Jungfrauen!',
        17: 'Du sollst nicht eine Verführerin aufziehen!',
        18: 'Wer einem Tier beiwohnt, sterbe des Todes!',
        19: 'Wer den Göttern opfert, sei im Banne! Einzig und allein dem Herrn!',
        20: 'Einen Fremdling sollst du nicht drücken noch quälen! Auch ihr seid Fremdlinge im Land Ägypten gewesen.',
        21: 'Ihr sollt nie Witwen und Waisen bedrücken!',
        22: 'Drückst du sie, dann schreit sie zu mir, und ich höre ihr Schreien.',
        23: 'Aufflammt mein Zorn, und mit dem Schwerte töt ich euch, und eure Weiber werden Witwen, und Waisen eure Kinder.',
        24: 'Leihst du Geld meinem Volk, dem Armen bei dir, sei ihm nie wie ein Wucherer! Zins sollt ihr ihm nicht auferlegen!',
        25: 'Pfändest du des Genossen Mantel, gib ihn zurück bis zum Sonnenuntergang!',
        26: 'Denn er ist seine einzige Hülle, für seine Haut sein Kleid. Worin soll er sich schlafen legen? Schreit er zu mir, dann höre ich darauf. Denn ich bin mitleidsvoll.',
        27: 'Du sollst Gott nicht lästern. Du sollst keinem Fürsten deines Volkes fluchen!',
        28: 'Hinterziehen sollst du nicht deine Fülle noch dein Tröpflein! Gib mir deiner Söhne Erstgeborenen!',
        29: 'So sollst du auch mit deinem Rinde und deinem Schafe tun! Bei seiner Mutter bleibe es sieben Tage! Am achten magst du es mir bringen.',
        30: 'Heilige Männer sollt ihr mir sein! Zerrissenes Wildfleisch sollt ihr nicht essen! Den Hunden sollt ihr es vorwerfen!',
    },
    23: {
        1: 'Du sollst kein Luggerücht annehmen! Reiche nicht die Hand dem Schuldigen, daß du unrecht Zeugnis gäbest!',
        2: 'Du sollst nicht einer Mehrheit zum Schlechten folgen! Du sollst nicht über einen Streitfall so abstimmen, daß du dich der Mehrheit beugest und das Recht biegest!',
        3: 'Den Reichen sollst du nicht in seinem Rechtsstreit beschönigen.',
        4: 'Triffst du deines Feindes Rind oder Esel verlaufen an, dann sollst du sie ihm zuführen!',
        5: 'Und siehst du deines Widersachers Esel unter seiner Last erliegen und bist du fertig mit seinem Absatteln, dann sollst du mit ihm noch rasten!',
        6: 'Du sollst nicht deines Armen Recht in seinem Rechtsstreit beugen!',
        7: 'Fern sollst du dich von lügenhafter Aussage halten! Wer ohne Schuld und im Recht ist, den bringe nicht ums Leben! Ich lasse den Schuldigen nicht ungestraft.',
        8: 'Du sollst kein Geschenk annehmen! Denn das Geschenk blendet Sehende und verdreht der Gerechten Sache.',
        9: 'Du sollst keinen Fremdling bedrücken! Ihr wißt ja selbst, wie es Fremdlingen zumute ist; ihr seid ja selbst Fremdlinge im Ägypterland gewesen!',
        10: 'Sechs Jahre sollst du dein Land besäen und seine Ernte heimsen!',
        11: 'Im siebten aber laß es brach liegen und gib es dann frei, daß deines Volkes Arme essen können! Und was sie übriglassen, soll das Tier des Feldes aufzehren! So sollst du auch mit deinem Weinberge und deinem Ölgarten tun!',
        12: 'Sechs Tage sollst du deine Werke wirken! Am siebten aber sollst du feiern, damit dein Rind und dein Esel ruhe und aufatme das Kind deiner Magd und der Fremdling!',
        13: 'In allem, was ich euch befehle, sollt ihr euch in acht nehmen! Der falschen Götter Namen sollt ihr nicht anrufen! Er soll aus deinem Munde nicht gehört werden!',
        14: 'Dreimal im Jahr sollst du mir Feste feiern!',
        15: 'Das Fest der ungesäuerten Brote sollst du halten! Sieben Tage sollst du nur ungesäuertes Brot essen, wie ich dir geboten, zur Zeit des Neumonds im Abib. An ihm bist du aus Ägypten fortgezogen. Mein Antlitz aber soll man nicht gabenleer schauen!',
        16: 'Und das Fest der Ernte, der Erstlinge deines Ertrages, dessen, womit den Acker du besätest, und am Jahresschluß das Fest der Lese, wenn du vom Felde deinen Ertrag erntest.',
        17: 'Dreimal im Jahre lasse sich alles Männliche bei dir vor dem Herrn, dem Herrn, sehen!',
        18: 'Du sollst nicht meines Opfers Blut mit Gesäuertem zusammen opfern! Nicht soll von meinen Festopfern das Fett bis zum Morgen noch da sein!',
        19: 'Von deines Ackers Erstlingen den ersten Abhub sollst du zum Hause des Herrn, deines Gottes, bringen! Du sollst kein Böckchen im Fett seiner Mutter braten!',
        20: 'Nun sende ich einen Engel vor dir her, dich auf dem Wege zu hüten und dich zur Stätte zu bringen, die ich bestimmt habe.',
        21: 'Nimm dich vor ihm in acht und hör auf seine Stimme! Sei gegen ihn nicht widerspenstig! Er kann euren Frevel nicht ertragen, weil mein Name in ihm ist.',
        22: 'Hörst du aber gehorsam auf seine Stimme und tust du alles, was ich sage, dann befeinde ich deine Feinde und dränge deine Dränger.',
        23: 'Geht mein Engel vor dir her und bringt er dich dann zu den Amoritern und Chittitern, Perizitern, Kanaanitern, Chiwitern und den Jebusitem, die ich ausrotte,',
        24: 'dann sollst du nicht ihre Götter anbeten und ihnen nicht dienen! Auch sollst du keine Abbilder von ihnen machen! Du sollst sie vielmehr niederreißen und zerschmettern ihre Denksteine!',
        25: 'Dient ihr aber dem Herrn, eurem Gott, dann segnet er dein Brot und dein Wasser, und Krankheit halte ich dir ferne.',
        26: 'Keine Fehlgebärende und Unfruchtbare wird in deinem Lande sein. Deiner Tage Zahl erfülle ich.',
        27: 'Und mein Grauen sende ich vor dir her, und dann erschrecke ich alle Völker, zu denen du gelangst, und mache, daß vor dir alle deine Feinde fliehen.',
        28: 'Vor dir her sende ich Hornissen, und sie vertreiben vor dir Chiwiter, Kanaaniter und Chittiter.',
        29: 'Aber nicht in einem Jahre will ich sie vor dir vertreiben, sonst würde das Land zur Wüste, und die wilden Tiere nähmen zu deinem Schaden überhand.',
        30: 'Nach und nach vertreibe ich sie vor dir, bis du zahlreich wirst und dann das Land besetzen kannst.',
        31: 'Und ich stecke dir die Gebiete vom Schilfmeer bis zum Philistermeer und von der Wüste bis zum Strome ab. Denn ich gebe in eure Hand des Landes Einwohner, daß du sie vor dir vertreibest.',
        32: 'Du darfst keinen Bund mit ihnen und ihren Göttern schließen.',
        33: 'Sie dürfen nicht in deinem Lande bleiben, daß sie dich nicht zur Sünde gegen mich verleiten. Denn dientest du ihren Göttern, so würde dir dies zum Falle.',
    },
    24: {
        1: 'Zu Moses aber hatte er gesprochen: "Steig zum Herrn empor, du, Aaron, Nadab und Abihu und siebzig von den Ältesten Israels und betet aus der Ferne an!',
        2: 'Moses allein trete zum Herrn! Die anderen dürfen nicht näher treten. Auch das Volk darf nicht mit ihm hinaufsteigen."',
        3: 'Und Moses kam und kündete dem Volke alle Worte des Herrn und alle Rechtssatzungen. Da antwortete das Volk einstimmig und sprach: "All die Worte, die der Herr gesprochen, wollen wir befolgen."',
        4: 'Und Moses schrieb alle Worte des Herrn nieder. Am anderen Morgen früh aber baute er einen Altar unten am Berge und zwölf Denksteine für die zwölf Stämme Israels.',
        5: 'Dann sandte er die Jungmänner der Israeliten hin, und sie brachten Brandopfer und schlachteten Stiere zu Dankopfern für den Herrn.',
        6: 'Moses aber nahm den einen Teil des Blutes und goß es in die Becken; den anderen Teil des Blutes sprengte er an den Altar.',
        7: 'Dann nahm er das Bundesbuch und las es dem Volke laut vor. Sie sprachen: "Alles, was der Herr geredet, wollen wir tun und darauf hören."',
        8: 'Da nahm Moses das Blut, sprengte es auf das Volk und sprach: "Dies ist das Blut des Bundes, den der Herr mit euch schließt auf alle diese Worte hin."',
        9: 'Dann stiegen Moses empor und Aaron, Nadab, Abihu mit siebzig der Ältesten Israels.',
        10: 'Da sahen sie Israels Gott, zu seinen Füßen etwas wie ein Werk aus Saphirplatten und wie der Himmel selbst so rein.',
        11: 'Aber an die Edlen der Israeliten hatte er nicht seine Hand gelegt. So schauten sie die Gottheit, konnten aber wie sonst essen und trinken.',
        12: 'Da sprach der Herr zu Moses: "Steig auf den Berg zu mir und bleibe hier! Ich will dir Steintafeln mit dem Gesetze und dem Gebote geben, das ich zu ihrer Weisung geschrieben habe."',
        13: 'Da stand Moses auf und sein Diener Josue. Und Moses stieg zu dem Berge der Gottheit empor.',
        14: 'Zu den Ältesten aber hatte er gesagt: "Wartet hier auf uns, bis wir zu euch zurückkehren! Bei euch sind ja Aaron und Hur. Wer einen Rechtsstreit hat, wende sich an sie!"',
        15: 'Und Moses stieg auf den Berg. Da verhüllte die Wolke den Berg.',
        16: 'Und des Herren Majestät ließ sich herab auf den Berg Sinai. Und die Wolke hüllte ihn sechs Tage ein. Am siebten Tage aber rief er Moses mitten aus der Wolke an.',
        17: 'Die Erscheinung der Majestät des Herrn aber war wie ein fressendes Feuer auf dem Bergesgipfel vor den Augen der Söhne Israels.',
        18: 'Und Moses kam mitten in die Wolke und stieg auf den Berg. Und dann weilte Moses auf dem Berge vierzig Tage und vierzig Nächte.',
    },
    25: {
        1: 'Der Herr aber sprach zu Moses also:',
        2: '"Sprich zu den Söhnen Israels, sie sollen für mich beisteuern! Von jedem, den sein Herz dazu treibt, sollt ihr Beisteuer für mich erheben!',
        3: 'Dies sei die Beisteuer, die ihr von ihnen erheben sollt: Gold, Silber, Kupfer,',
        4: 'Purpur, blau und rot, Karmesin, Linnen, Ziegenhaar,',
        5: 'gegerbte Widderfelle, Seekuhhäute, Akazienholz,',
        6: 'Öl für den Leuchter, Spezereien zum Salböl und zum Räucherwerk, dem köstlich duftenden,',
        7: 'Onyxsteine und andere Edelsteine zum Besatz des Schulterkleides und der Tasche!',
        8: 'Ein Heiligtum sollen sie mir machen, daß ich in ihrer Mitte wohne!',
        9: 'Genau nach dem, was ich dir zeige, nach dem Muster der Wohnung und dem Muster all ihrer Geräte, so sollt ihr es machen!',
        10: 'Sie sollen demnach von Akazienholz eine Lade machen, zweieinhalb Ellen lang, anderthalb hoch und breit!',
        11: 'Überziehe sie mit reinem Gold! Überziehe sie ganz von innen und von außen! Und mach einen goldenen Kranz ringsum an ihr!',
        12: 'Vier goldene Ringe gieße für sie. An den vier Füßen bringe sie an, zwei Ringe auf der einen Seite, zwei auf der anderen!',
        13: 'Mache Stangen von Akazien und überziehe sie mit Gold!',
        14: 'Paß diese Stangen in die Ringe an der Seite der Lade, die Lade daran zu tragen!',
        15: 'Die Stangen seien in den Ringen der Lade also, daß sie nicht herausschlüpfen!',
        16: 'In diese Lade leg das Zeugnis, das ich dir geben werde!',
        17: 'Mach aus reinem Gold eine Deckplatte zweieinhalb Ellen lang, anderthalb Ellen breit!',
        18: 'Mach zwei Cherube, aus Gold getrieben, an beiden Enden der Deckplatte!',
        19: 'Festige den einen Cherub an dem einen Ende, den anderen am anderen Ende! Auf der Deckplatte sollst du die Cherube an ihren beiden Enden aufstellen!',
        20: 'Nach oben sollen die Cherube die Flügel breiten, mit ihren Flügeln die Deckplatte schirmend, das Antlitz einander zugekehrt! Nach der Deckplatte hin seien der Cherube Gesichter gerichtet!',
        21: 'Lege die Deckplatte oben auf die Lade! In die Lade sollst du das Zeugnis legen, das ich dir geben werde!',
        22: 'Ich bezeuge mich dir dort und rede mit dir von dieser Deckplatte zwischen den beiden Cheruben auf der Zeugnislade, sooft ich dir Befehle an die Israeliten gebe.',
        23: 'Mach dann aus Akazienholz einen Tisch zwei Ellen lang, eine -Elle breit und anderthalb hoch!',
        24: 'Überziehe ihn mit reinem Gold! Mach ihm einen goldenen Kranz ringsum!',
        25: 'Mach ihm eine Leiste, handbreit, ringsum und einen goldenen Kranz an seiner Leiste ringsum!',
        26: 'Mach ihm vier goldene Ringe und bringe die Ringe an die vier Ecken bei seinen Füßen!',
        27: 'Dicht an der Leiste seien diese Ringe als Stangenhalter, um den Tisch zu tragen!',
        28: 'Die Stangen mache aus Akazienholz und überziehe sie mit Gold! An ihnen werde der Tisch getragen!',
        29: 'Mach für ihn Schüsseln, Schalen, Kannen und Becher zum Darbringen des Trankopfers! Aus reinem Gold stelle sie her!',
        30: 'Und auf dem Tisch lege Schaubrote beständig vor mich hin!',
        31: 'Dann mach aus reinem Gold einen Leuchter! Der Leuchter und sein Fußgestell samt seinem Schaft seien ganz gediegene Arbeit! Blumenkelche, Knospen und Blüten daraus seien an ihm!',
        32: 'Sechs Röhren gehen von seinen Seiten aus, drei Röhren auf der einen Seite des Leuchters und drei auf der anderen Seite des Leuchters.',
        33: 'Drei Blumenkelche, mandelförmig, seien an jeder Röhre, mit Knospen und mit Blüten, auf der einen und der anderen Seite; so an den sechs Röhren, die von dem Leuchter ausgehen.',
        34: 'Am Leuchter selbst seien vier Blumenkelche, mandelförmig, mit Knospen und mit Blüten!',
        35: 'Und zwar sei eine Knospe unter jedem der drei Röhrenpaare an ihm, an den sechs Röhren, die von dem Leuchter ausgehen!',
        36: 'Aus einem Stück sollen ihre Knospen und ihre Röhren mit ihm sein, aus feinem Gold getrieben!',
        37: 'Mach sieben Lampen für ihn! Man setze ihm diese Lampen so auf, daß er die ihm zugekehrte Seite beleuchte!',
        38: 'Aus reinem Gold seien seine Lichtscheren und Pfannen!',
        39: 'Einen Barren feinen Goldes sollst du an ihn samt allen jenen Stücken verwenden!',
        40: 'So schau! So baue genau nach dem Muster, das auf dem Berge dir gezeigt worden ist!"',
    },
    26: {
        1: '"Die Wohnung aber sollst du aus zehn Teppichen von gezwirntem Linnen, Purpur, blau und rot, und Karmesin fertigen! Mit Cheruben nach Kunstwirkers Art sollst du sie machen!',
        2: 'Jeder Teppich sei achtundzwanzig Ellen lang, vier Ellen breit! Ein Maß für alle Teppiche!',
        3: 'Je fünf der Teppiche seien zusammengeheftet!',
        4: 'Mach von blauem Purpur Schleifen am Saume des letzten Teppichs der einen Fläche, desgleichen am Saume des letzten Teppichs der anderen Fläche!',
        5: 'An dem einen Teppich sollst du fünfzig Schleifen machen und fünfzig Schleifen an dem Rande des Teppichs der anderen Fläche, daß sich die Schleifen gegenüberstehen!',
        6: 'Mach fünfzig goldene Haken und hefte die Teppiche damit zusammen, daß die Wohnung ein Ganzes werde!',
        7: 'Mach Teppiche aus Ziegenhaar zu einem Zelt über der Wohnung! Dazu sollst du elf der Teppiche verwenden!',
        8: 'Jeder Teppich sei dreißig Ellen lang, vier Ellen breit! Ein Maß für alle elf Teppiche!',
        9: 'Hefte fünf der Teppiche für sich zusammen, ebenso die anderen sechs! Den sechsten Teppich aber an des Zeltes Vorderseite nimm doppelt!',
        10: 'Mach fünfzig Schleifen an dem einen Saume des letzten Teppichs der einen Fläche, desgleichen fünfzig an dem Rande des Teppichs der zweiten Fläche!',
        11: 'Mach fünfzig Kupferhaken! Ziehe die Haken durch die Schleifen und füge so das Zelt zusammen, daß es ein Ganzes werde!',
        12: 'Von dem überschüssigen Überhange an den Zeltteppichen sollst du die eine Hälfte über die Rückseite der Wohnung hängen!',
        13: 'Auf beiden Seiten hänge je eine, Elle am Überschuß in der Länge der Zeltteppiche über die Seiten der Wohnung und hülle sie auf beiden Seiten!',
        14: 'Mach für das Zelt eine Überdecke aus gegerbten Widderfellen und aus Seekuhhäuten eine weitere Überdecke darüber!',
        15: 'Die Bretter zur Wohnung mache aus Akazienholz, standfest!',
        16: 'Zehn Ellen lang sei jedes Brett, anderthalb Ellen breit!',
        17: 'Zwei Zapfen habe jedes Brett zur gegenseitigem Versprießung! So sollst du es mit allen Brettern für die Wohnung machen!',
        18: 'An Brettern für die Wohnung stelle zwanzig Bretter für die Südseite her!',
        19: 'Vierzig Fußgestelle aus Silber sollst du unter die Zwanzig Bretter machen! Zwei Füße unter jedes Brett für seine beiden Zapfen!',
        20: 'Desgleichen für die andere Seite der Wohnung gegen Norden zwanzig Bretter!',
        21: 'Und vierzig Silberfüße, zwei Füße unter jedes Brett!',
        22: 'Und für die Westseite der Wohnung mach sechs Bretter!',
        23: 'Zwei Bretter mach für die Winkel an der Wohnung auf der Rückseite!',
        24: 'Sie seien unten doppelkantig und am Kopfende kreisrund! So sei es für beide! Sie sollen die beiden Winkel bilden!',
        25: 'Acht Bretter seien es somit und dazu ihre Silberfußgestelle, somit sechzehn Fußgestelle, je zwei als Fußgestell für jedes Brett!',
        26: 'Dann mach fünf Riegel aus Akazienholz für die Bretter auf der einen Seite der Wohnung',
        27: 'sowie fünf Riegel für die Bretter auf der anderen Seite und fünf für die Bretter an der westlichen Hinterseite der Wohnung!',
        28: 'Der mittlere Riegel laufe in der Bretter Mitte von einem Ende zum anderen durch!',
        29: 'Die Bretter sollst du mit Gold überziehen und aus Gold die Ringe zur Aufnahme für die Riegel machen. Dann überziehe die Riegel mit Gold!',
        30: 'So erstelle die Wohnung nach ihrer Ordnung, wie sie dir auf dem Berge gezeigt worden ist!',
        31: 'Mach einen Vorhang aus blauem und aus rotem Purpur, aus Karmesin und aus gezwirntem Linnen! In Kunstwirkarbeit mache man ihn mit Cheruben!',
        32: 'Hänge ihn an vier Säulen aus Akazienholz, mit Gold überzogen, mit goldenen Stiften und vier Silberfüßen!',
        33: 'Den Vorhang hänge an die Haken! Hinter diesen Vorhang bringe die Lade des Zeugnisses! So scheide euch der Vorhang das Heilige und das Allerheiligste!',
        34: 'Und auf die Lade des Zeugnisses setze im Allerheiligsten die Deckplatte!',
        35: 'Den Tisch stelle außerhalb des Vorhanges, den Leuchter dem Tisch gegenüber, auf der Wohnung Südseite! Den Tisch sollst du auf die Nordseite stellen!',
        36: 'Mach einen Vorhang für des Zeltes Öffnung aus blauem und aus rotem Purpur, Karmesin und aus gezwirntem Linnen in Buntwirkarbeit.',
        37: 'Und für den Vorhang mach fünf Säulen aus Akazienholz! Überziehe sie mit Gold und gieße für sie fünf Kupferfußgestelle!',
    },
    27: {
        1: 'Mach aus Akazienholz den Altar, fünf Ellen lang, fünf Ellen breit! Viereckig sei der Altar und drei Ellen hoch!',
        2: 'An den vier Ecken bringe seine Hörner so an, daß die Hörner von ihm ausgehen! Überziehe ihn mit Kupfer!',
        3: 'Mach seine Töpfe für die Fettasche und seine Schaufeln, Becken, Gabeln, Pfannen, alle seine Sachen sollst du aus Kupfer herstellen!',
        4: 'Mache für ihn ein Gitter, Netzwerk aus Kupfer! Bringe an dem Netz vier Kupferringe an, an den vier Ecken des Altares!',
        5: 'Befestige dies unten so am Altargesims, daß das Netz noch bis zur Mitte des Altares reiche!',
        6: 'Mach für den Altar Stangen aus Akazienholz und überziehe sie mit Kupfer!',
        7: 'Man bringe seine Stangen in die Ringe, damit sie in den Ringen bleiben zu beiden Seiten des Altares, wenn man ihn trägt!',
        8: 'Aus Brettern sollst du ihn machen, daß er hohl sei! Wie man dir auf dem Berge zu schauen gegeben, so sollen sie es machen!',
        9: 'Der Wohnung Vorhof mach so: Vorhofumhänge für die Südseite aus gezwirntem Linnen, für diese eine Seite hundert Ellen lang!',
        10: 'Dazu zwanzig Säulen nebst ihren zwanzig Kupferfüßen! Der Säulen Nägel seien, wie ihre Ringe, silbern!',
        11: 'Desgleichen für die Langseite des Nordens Umhänge von hundert Ellen Länge, dazu die zwanzig Säulen mit ihren zwanzig Kupferfüßen! Der Säulen Nägel seien, wie ihre Ringe, silbern!',
        12: 'Des Vorhofes westliche Breitseite habe Umhänge von fünfzig Ellen, dazu zehn Säulen nebst ihren zehn Füßen!',
        13: 'Des Vorhofes östliche Breitseite habe fünfzig Ellen!',
        14: 'Fünfzehn Ellen Umhänge sollen auf die eine Seite kommen, dazu drei Säulen nebst drei Füßen!',
        15: 'Desgleichen auf die andere Seite fünfzehn Ellen Umhänge, dazu drei Säulen mit drei Füßen!',
        16: 'Des Vorhofes Tor habe einen Vorhang, zwanzig Ellen breit, von blauem und von rotem Purpur, Karmesin, gezwirntem Linnen, bunt gewirkt, dazu vier Säulen nebst vier Füßen!',
        17: 'Des Vorhofes Säulen alle seien mit Silberringen ringsumher versehen! Auch ihre Nägel seien silbern, ihre Füße aber kupfern!',
        18: 'Des Vorhofes Länge sei hundert Ellen, die Breite fünfzig, die Höhe fünf, aus gezwirntem Linnen! Die Füße aber seien kupfern!',
        19: 'Aus Kupfer seien alle die Geräte in der Wohnung nebst ihrem ganzen Zubehör, desgleichen alle ihre Pflöcke und des Vorhofes Pflöcke!',
        20: 'Du aber sollst den Israeliten befehlen, dir lauteres Öl aus zerstoßenen Oliven für den Leuchter zu holen, um die ewige Lampe anzuzünden!',
        21: 'Im Festgezelt außerhalb des Vorhangs, vor dem Zeugnis, richte ihn Aaron mit seinen Söhnen zu, daß er vom Abend bis zum Morgen vor dem Herrn sei! Als ewige Verpflichtung sei dies den Israeliten für alle Geschlechter auferlegt!"',
    },
    28: {
        1: '"Berufe deinen Bruder Aaron und nächst ihm seine Söhne aus all den Söhnen Israels zu dir, daß er mir Priester sei! Aaron, Nadab, Abihu, Eleazar und Itamar, die Söhne Aarons!',
        2: 'Mach deinem Bruder Aaron Kleider für das Heiligtum, für den Anstand und die Würde!',
        3: 'Du sollst dich mit allen Leuten weisen Sinnes besprechen, wen ich mit weisem Geiste erfülle, auf daß sie Aarons Kleider machen, um ihn zu weihen, daß er mir Priesterdienste tue!',
        4: 'Dies sind die Kleider, die sie machen sollen: Die Tasche, das Schulterkleid, das Oberkleid und den Leibrock aus gewürfeltem Stoff, den Kopfbund und den Gürtel. So sollen sie deinem Bruder Aaron mit seinen Söhnen heilige Kleider machen, daß er mir Priesterdienste tue!',
        5: 'Und dazu nehmen sollen sie Gold, blauen und roten Purpur, Karmesin und Linnen!',
        6: 'Das Schulterkleid sollen sie aus Gold machen, aus blauem und rotem Purpur, Karmesin und Linnen in kunstgewirkter Arbeit!',
        7: 'Zwei Schulterstücke, unter sich verbunden, soll es haben! Auf seinen beiden Enden werde es geknüpft!',
        8: 'Das Band zum Umbinden sei von gleicher Arbeit. Ein Stück mit ihm, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen!',
        9: 'Nimm zwei Onyxsteine und grabe darein der Söhne Israels Namen!',
        10: 'Sechs ihrer Namen auf den einen Stein, die übrigens sechs Namen auf den zweiten Stein, nach ihrer Geburtsfolge!',
        11: 'In Steinschneideart, in Siegelstich sollst du in die beiden Steine der Söhne Israels Namen graben und sie in goldenes Geflecht fassen!',
        12: 'Setze die beiden Steine auf die Schulterstücke des Schulterkleides als Steine des Gedenkens an die Söhne Israels! Im Dienst des Herrn trage Aaron ihre Namen auf den Schultern zum Gedächtnis!',
        13: 'Sodann mach Goldgeflechte',
        14: 'und aus reinem Gold zwei Kettchen! Du sollst sie in gedrehten Schnüren herstellen! Befestige an den Goldgeflechten die Schnurkettchen!',
        15: 'Dann mach in Kunstwirkarbeit eine Lostasche! Wie das Schulterkleid sollst du sie machen! Aus Gold, aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen sollst du sie machen!',
        16: 'Viereckig sei sie, doppelt gelegt, je eine Spanne lang und breit!',
        17: 'Besetze sie mit Edelsteinbesatz in vier Steinreihen! Karneol, Topas und Smaragd sei die erste Reihe!',
        18: 'Die zweite Reihe Rubin, Saphir und Jaspis.',
        19: 'Die dritte Reihe Hyazinth, Achat und Amethyst.',
        20: 'Die vierte Reihe Chrysolith, Onyx und Beryll. In ihrer Einfassung seien sie goldumflochten!',
        21: 'Die Steine sollen für der Söhne Israels Namen da sein, zwölf nach ihren Namen. In jeden sei der Name eines der zwölf Stämme eingegraben!',
        22: 'Mach an die Tasche rein goldene Schnurkettchen!',
        23: 'Bringe an der Tasche auch zwei goldene Ringe an! Befestige die beiden Ringe an den Enden der Tasche!',
        24: 'Befestige die beiden goldenen Schnüre in den beiden Ringen an den Enden der Tasche!',
        25: 'Der beiden Schnüre beide Enden sollst du an die zwei Geflechte befestigen und diese an die Schulterstücke vorn am Schulterkleid!',
        26: 'Mach zwei goldene Ringe und setze sie an die beiden Enden der Tasche, an ihren Rand, nach innen dem Schulterkleid zu!',
        27: 'Mach noch zwei goldene Ringe und befestige sie an den beiden Schulterstücken des Schulterkleides, unten an der Vorderseite, bei der Knüpfung, doch oberhalb der Schulterkleidbinde!',
        28: 'Man soll die Tasche samt den Ringen an die Ringe des Schulterkleides mit blauen Purpurschnüren ketten, daß sie über der Schulterkleidbinde sei und sich die Tasche nicht vom Schulterkleide trenne!',
        29: 'Aaron trage in der Tasche auf der Brust der Söhne Israels Namen, wenn er ins Heiligtum geht, zur ständigen Erinnerung des Herrn!',
        30: 'Und in die Tasche lege die Urim und Tummim, daß sie auf Aarons Brust seien, wenn er vor den Herrn tritt! Also trage Aaron für die Söhne Israels die Tasche vor dem Herrn beständig auf der Brust!',
        31: 'Das Obergewand zum Schulterkleid mache aus blauem Purpur!',
        32: 'In seiner Mitte sei seine Kopföffnung! Und diese Öffnung habe einen Saum ringsum in Webart! Wie eine Panzeröffnung soll es eine solche haben, daß es nicht zerreiße!',
        33: 'Mach an dem Saum Granatäpfel von blauem und rotem Purpur und Karmesin, rings an seinem Saum, und goldene Glöckchen mitten darin ringsum!',
        34: 'Goldene Glöckchen sollen mit Granatäpfeln am Saum des Oberkleides ringsum abwechseln!',
        35: 'Beim Dienste trage es Aaron, und sein Geräusch werde gehört, wenn er vor den Herrn ins Heiligtum geht und wenn er herausgeht, daß er nicht sterbe!',
        36: "Dann mach aus reinem Gold ein Blatt und grabe darauf in Siegelstich: 'Heiligtum des Herrn'!",
        37: 'Befestige dies mit blauer Purpurschnur am Kopfbunde! Vorn am Kopfbunde sei es!',
        38: 'Es sei auf Aarons Stirn! So ersetze Aaron die Fehler an heiligen Gaben, die Israels Söhne darbringen, bei all ihren heiligen Opfergaben! Auf seiner Stirn sei es beständig, daß ihnen Wohlgefallen vor dem Herrn werde!',
        39: 'Den Leibrock webe aus Linnen, würfelförmig ausgemustert! Einen Kopfbund mach aus Linnen! Und einen Gürtel in buntgewirkter Arbeit sollst du machen!',
        40: 'Für Aarons Söhne sollst du Leibröcke herstellen; mach auch Gürtel, und hohe Mützen sollst du ihnen für den Anstand und die Würde machen!',
        41: 'Kleide darein deinen Bruder Aaron und seine Söhne bei ihm! Dann salbe sie, fülle ihre Hand und weihe sie, daß sie mir Priesterdienste tun!',
        42: 'Fertige ihnen Linnenbeinkleider zur Verhüllung der Blöße! Von den Hüften bis zu den Schenkeln sollen sie reichen!',
        43: 'Aaron und seine Söhne sollen sie tragen, wenn sie zum Festgezelt eingehen oder an den Altar treten, um Dienst im Heiligtum zu tun! Sonst würden sie Schuld auf sich laden und sterben. Dies gelte ihm und seinem Stamm als ewige Verpflichtung!"',
    },
    29: {
        1: '"Dies ist der Hergang, den du beachten sollst, wenn du sie zum Priesterdienst für mich weihst: Nimm einen jungen Stier und zwei fehlerlose Widder,',
        2: 'ungesäuertes Brot, ungesäuerte, ölbestrichene Kuchen und ungesäuerte, ölbestrichene Fladen! Aus Weizenmehl sollst du sie machen!',
        3: 'Leg sie in einen Korb und bringe sie in dem Korbe her! Dazu den Farren und die beiden Widder!',
        4: 'Dann führe Aaron mit den Söhnen an des Bundeszeltes Eingang und bade sie in Wasser!',
        5: 'Dann nimm die Gewänder! Bekleide Aaron mit dem Leibrock und mit dem Oberkleid zum Schulterkleid, mit dem Schulterkleid selbst und mit der Tasche und binde ihm des Schulterkleides Binde um!',
        6: 'Setze ihm den Kopfbund auf sein Haupt! Befestige am Kopfbunde das heilige Diadem!',
        7: 'Dann nimm das Salböl, gieße es auf sein Haupt und salbe ihn!',
        8: 'Alsdann sollst du seine Söhne kommen lassen; bekleide sie dann mit Leibröcken!',
        9: 'Umgürte sie mit einem Gürtel, Aaron wie seine Söhne! Setz ihnen Mützen auf! So stehe ihnen kraft ewiger Ordnung das Priesteramt zu! Nun fülle Aarons und seiner Söhne Hand.',
        10: 'Dann bringe den Farren zu dem Festgezelt her, und Aaron und seine Söhne sollen ihre Hände auf des Farren Kopf legen!',
        11: 'Dann schlachte vor dem Herrn den Farren an dem Eingang zum Festgezelt!',
        12: 'Nimm von dem Farrenblut und tu es mit deinem Finger an die Altarhörner! Das andere Blut sollst du ganz auf den Altarsockel gießen!',
        13: 'Nimm alles Fett der Eingeweidedecke, den Leberlappen und die beiden Nieren samt dem Fett daran und laß es auf dem Altar verrauchen!',
        14: 'Das Fleisch des Farren, sein Fell und seinen Mist sollst du außer Lagers verbrennen! Ein Sündopfer ist dies.',
        15: 'Dann sollst du den einen Widder nehmen; Aaron aber und seine Söhne sollen ihre Hände auf des Widders Kopf legen!',
        16: 'Dann schlachte den Widder, nimm sein Blut und sprenge es rings um den Altar!',
        17: 'Dann sollst du den Widder zerstückeln; hierauf wasche seine Eingeweide und Beine und lege sie zu seinen Rumpfstücken und seinem Kopf!',
        18: 'Dann laß den ganzen Widder auf dem Altar verrauchen! Brandopfer ist es für den Herrn, ein süßer Duft. Ein Mahl ist es für den Herrn.',
        19: 'Dann nimm den zweiten Widder, und Aaron und seine Söhne sollen ihre Hände auf des Widders Kopf legen!',
        20: 'Dann schlachte den Widder, nimm von seinem Blut und bring es an das rechte Ohrläppchen Aarons und seiner Söhne und an den rechten Daumen und die rechte große Zehe! Das andere Blut sprenge rings um den Altar!',
        21: 'Dann nimm von dem Blut am Altar und von dem Salböl! Besprenge damit Aaron und seine Gewänder, sodann die Aaronssöhne und ihre Gewänder, daß er und seine Gewandung sowie seine Söhne und ihre Gewandung geweiht werden!',
        22: 'Dann nimm des Widders Fett, den Fettschwanz und das Fett der Eingeweidedecke, den Leberlappen und die beiden Nieren, das Fett davon und die rechte Keule, weil es ein Weihewidder ist,',
        23: 'und einen Brotlaib, einen ölgebackenen Kuchen und einen Fladen aus dem Korb der ungesäuerten Brote vor dem Herrn!',
        24: 'Und leg das Ganze dem Aaron und den Söhnen auf die Hände und bringe es vor dem Herrn als Abgabe dar!',
        25: 'Dann nimm es aus ihrer Hand und laß es auf dem Brandopferaltar aufdampfen zu süßem Duft vor dem Herrn! Ein Mahl für den Herrn ist es.',
        26: 'Dann nimm die Brust vom Weihewidder, der für Aaron gilt, und bringe sie vor dem Herrn als Abgabe dar! Dann sei sie dein Teil!',
        27: 'Weihe die Brust der Abgabe und die Weihegabekeule, von denen die eine sonst geopfert, die andere abgeliefert wird, vom Weiheopferwidder, zum Unterschied von dem, was sonst Aaron und seine Söhne bekommen!',
        28: 'Dies falle sonst Aaron und seinen Söhnen zu, kraft einer für die Israeliten ewig geltenden Verpflichtung; denn dies ist eine Abgabe. Eine Abgabe der Söhne Israels sei es von ihren Mahlopfern, ihre Abgabe für den Herrn!',
        29: 'Aarons heilige Gewänder sollen seinen Söhnen nach ihm zufallen, um sie darin zu salben und ihre Hand darin zu füllen!',
        30: 'Wer von seinen Söhnen an seiner Statt Priester ist, der soll sie sieben Tage anziehen, wenn er ins Festgezelt zum Dienst im Heiligtum kommt!',
        31: 'Den Weiheopferwidder aber sollst du nehmen, und dann koche sein Fleisch an heiliger Stätte!',
        32: 'Das Widderfleisch verzehre Aaron mit seinen Söhnen samt dem Brot im Korb am Eingang zum Festgezelt!',
        33: 'Dies sollen die verzehren, um deretwillen dieses Sühneopfer vollzogen wird, um ihre Hand zu füllen und sie zu weihen. Ein Unbefugter esse nicht davon, weil es heilige Dinge sind!',
        34: 'Und bleibt vom Fleisch des Weiheopfers und vom Brot bis zum Morgen etwas übrig, verbrenne, was übrigbleibt! Man darf es nicht essen, weil es ein heilig Ding ward.',
        35: 'Tu so mit Aaron und seinen Söhnen, ganz so, wie ich dir gebiete! Fülle ihnen sieben Tage die Hand!',
        36: 'Und einen Sündopferstier sollst du bereiten für jeden Tag zum Sühnevollzug! Entsündige den Altar durch dein Sühnewerk und salbe ihn, um ihn zu weihen!',
        37: 'Sieben Tage lang sollst du die Sühnehandlungen am Altar vollziehen; so weihe ihn ein! Dann wird der Altar hochheilig. Wer den Altar berührt, wird selber heilig.',
        38: 'Das ist es, was du auf dem Altar herrichten sollst: Zwei einjährige Lämmer Tag für Tag als Regel!',
        39: 'Am Morgen sollst du das eine Lamm bereiten, das zweite gegen Abend!',
        40: 'Zum einen Lamm komme ein Zehntel Feinmehl, gemengt mit einem Viertelkrug Öl aus zerstoßenen Oliven, dazu ein Trankopfer aus einem Viertel Wein!',
        41: 'Das andere Lamm sollst du gegen Abend bereiten! Dabei sollst du, wie beim morgendlichen Speise- und Trankopfer tun, zu süßem Duft! Ein Mahl für den Herrn ist es,',
        42: 'das stetige Brandopfer für eure Geschlechter, am Eingang zum Festgezelt vor dem Herrn, wo ich mich euch offenbare, dort mit dir redend.',
        43: 'Ich will mich daselbst den Söhnen Israels offenbaren. Durch meine Herrlichkeit wird es geweiht.',
        44: 'So weihe ich das Festgezelt und den Altar. Auch Aaron weihe ich und seine Söhne, daß sie mir Priesterdienste tun.',
        45: 'Ich wohne mitten unter Israels Söhnen und diene ihnen als Schutzgott.',
        46: 'Und sie erfahren dann, daß ich der Herr, ihr Gott bin, der sie aus dem Ägypterland geführt, um unter ihnen zu verweilen, ich, der Herr, ihr Gott."',
    },
    30: {
        1: '"Mach einen Rauchaltar! Mach ihn aus Akazienholz!',
        2: 'Viereckig sei er, eine Elle lang und eine breit, zwei hoch! Seine Hörner sollen von ihm ausgehen!',
        3: 'Überziehe ihn mit reinem Gold, seine Platte, seine Wände ringsum und seine Hörner und mach ihm einen goldenen Kranz ringsum!',
        4: 'Zwei goldene Ringe sollst du unterhalb des Kranzes an den beiden Seiten machen! An seinen Seiten sollst du sie machen, daß sie Gehäuse der Stangen seien, ihn daran zu tragen!',
        5: 'Die Stangen mach aus Akazienholz und überzieh sie mit Gold!',
        6: 'Stelle ihn vor den Vorhang vor der Lade des Zeugnisses und vor den Deckel über dem Zeugnis, wo ich mich dir offenbaren werde!',
        7: 'Aaron räuchere darauf wohlriechendes Räucherwerk! Er soll es alle Morgen räuchern, wenn er die Lampen richtet!',
        8: 'Und wenn Aaron abends die Lampen aufsteckt, dann soll er räuchern! In euren Geschlechtern sei vor dem Herrn ein stetig Rauchopfer!',
        9: 'Ihr sollt auf ihm kein fremdes Räucherwerk darbringen, nicht Brand-, nicht Speiseopfer! Ihr sollt darauf kein Trankopfer ausgießen!',
        10: 'Einmal im Jahr verrichte Aaron an seinen Hörnern die Sühnehandlung! Einmal im Jahr soll er daran durch das Versöhnungssündenopferblut die Sühne in euren Geschlechtern vornehen! Dem Herrn ist er hochheilig."',
        11: 'Und der Herr redete mit Moses also:',
        12: '"Erhebst du der Söhne Israels Zahl bei ihrer Musterung, dann sollen sie dem Herrn ein Lösegeld für ihr Leben geben, Mann für Mann, wenn man sie mustert! Dann befällt sie keine Plage, wenn man sie mustert.',
        13: 'Wer der Musterung unterliegt, der soll die Hälfte des heiligen Ringes zahlen! Zwanzig Korn sind ein gemeiner Ring; dieser gilt nur als halber Ring bei einer Abgabe für den Herrn.',
        14: 'Wer der Musterung unterliegt, von zwanzig Jahren und darüber, soll für den Herrn die Abgabe geben!',
        15: 'Der Reiche gebe nicht mehr, der Arme nicht weniger als einen halben Ring, wenn sie die Abgabe für den Herrn entrichten, um euer Leben zu lösen!',
        16: 'Nimm von den Söhnen Israels das Sühnegeld und gib es für den Dienst am Festgezelt! So wirke es den Söhnen Israels beim Herrn ein Gedenken und ihres Lebens Lösung!"',
        17: 'Der Herr sprach zu Moses:',
        18: '"Mach dir ein Kupferbecken mit kupfernem Gestell zum Waschen und stelle es zwischen Festgezelt und Altar und gieße Wasser darein!',
        19: 'Daraus sollen sich Aaron und die Söhne Hände und Füße waschen!',
        20: 'Wenn sie zum Festgezelt kommen, sollen sie sich waschen, daß sie nicht sterben, oder wenn sie beim Dienst zum Altare treten, ein Mahl für den Herrn aufdampfen zu lassen,',
        21: 'dann sollen sie Hände und Füße waschen, daß sie nicht sterben! Dies sei ihnen ewige Pflicht, ihm sowie seinem Stamm für ihre Geschlechter!"',
        22: 'Der Herr sprach zu Moses also:',
        23: '"Nimm dir Balsamessenz und reine Myrrhe fünfhundert, und Zimt halb soviel, zweihundertfünfzig, Gewürzrohr, zweihundertfünfzig,',
        24: 'und Kassia, fünfhundert nach dem heiligen Ring, und einen Krug voll Olivenöl!',
        25: 'Und mache es zu heiligem Salböl, zu würziger Salbe, zu eines Salbenmischers Werk! Ein heilig Salböl soll es werden!',
        26: 'Salbe damit das Festgezelt und die Lade des Zeugnisses,',
        27: 'den Tisch und alle seine Geräte, den Leuchter und sein Zubehör, den Rauchaltar,',
        28: 'den Brandopferaltar und alle seine Geräte, das Becken und sein Gestell!',
        29: 'So weihe sie, daß sie hochheilig seien! Wer sie berührt, wird gleichfalls heilig.',
        30: 'Auch Aaron und seine Söhne sollst du salben; so weihe sie, daß sie mir Priester seien!',
        31: "Sprich zu den Söhnen Israels: 'Ein heilig Salböl sei mir dies für eure Geschlechter!",
        32: 'Auf keines Menschen Leib darf es gegossen werden! Ihr dürft in seiner Mischung für euch nichts Gleiches machen. Ein heilig Ding ist es. Ein heilig Ding bleibe es euch.',
        33: 'Wer solches mischt und davon an einen Unbefugten bringt, werde aus seinem Volke gestrichen!\'"',
        34: 'Der Herr sprach zu Moses: "Nimm Spezereien, Tropfharz, Räucherklaue, wohlriechendes Harz und reinen Weihrauch, alles zu gleichen Teilen!',
        35: 'Mach daraus ein Räucherwerk, eine würzige Mischung, eines Salbenmischers Werk, scharf, rein, ein heilig Ding!',
        36: 'Verreibe davon staubfein und bringe davon vor das Zeugnis ins Festgezelt, wo ich mich dir offenbaren werde! Hochheilig sei es euch!',
        37: 'Das Räucherwerk, das du machst, dürft ihr für euch nicht mehr nachmachen. Ein heilig Ding für den Herrn sei es dir!',
        38: 'Wer gleiches macht, daran zu riechen, werde aus seinem Volke gestrichen!"',
    },
    31: {
        1: 'Der Herr sprach zu Moses:',
        2: '"Sieh! Ich berufe Besalel, des Uri Sohn, den Enkel Hurs, vom Stamme Juda.',
        3: 'Ich erfülle ihn mit Gottesgeist, mit Weisheit, Einsicht und Wissen um jeglich Werk,',
        4: 'um Pläne zu ersinnen und sie in Gold, Silber und Kupfer auszuführen,',
        5: 'im Schnitt von Steinen zu Füllungen und im Schnitt von Hölzern, in vielgestaltiger Ausführung.',
        6: 'Oholiab, den Sohn Achisamaks, vom Danstamme gebe ich ihm bei und verleihe Weisheit allen anderen Künstlern, daß sie alles machen, was ich dir befehle.',
        7: 'Das Festgezelt und die Lade des Zeugnisses, die Deckplatte darüber und die anderen Geräte im Zelt,',
        8: 'den Tisch und seine Geräte, den reinen Leuchter mit all seinen Geräten, den Rauchaltar,',
        9: 'den Altar für Brandopfer und alle seine Geräte, das Becken mit seinem Gestell,',
        10: 'die feineren Schutzdecken und die Gewänder für das Heiligtum, für Aaron, den Priester, und die Gewänder seiner Söhne für den priesterlichen Dienst,',
        11: 'das Salböl und das würzige Rauchwerk für das Heiligtum. Ganz wie ich es dir befehle, sollen sie es machen!"',
        12: 'Und der Herr sprach zu Moses:',
        13: '"Sag dies den Söhnen Israels: \'Beobachtet doch meine Ruhetage! Ein Zeichen zwischen mir und euch ist ein solcher in euren Geschlechtern, auf daß man wisse, daß ich, der Herr, euch heilige.',
        14: 'Haltet auch den Sabbat! Er sei euch ein heilig Ding! Wer ihn entweiht, sterbe des Todes! Wer an ihm Arbeit tut, solch Wesen werde getilgt aus seinem Volke!',
        15: "Sechs Tage werde Arbeit getan! Am siebten Tage aber ist der rechte Ruhetag, ein heilig Ding dem Herrn! Wer am Sabbat Arbeit tut, sei des Todes!'",
        16: 'So sollen die Söhne Israels den Sabbat halten! Zum ewigen Bunde sollen sie den Sabbat in ihren Geschlechtern machen!',
        17: 'Er sei ein Zeichen zwischen mir und den Söhnen Israels für immer! Denn in sechs Tagen hat der Herr den Himmel und die Erde gemacht. Am siebten Tage aber hat er aufatmend geruht."',
        18: 'Und er übergab Moses, nachdem er mit ihm auf dem Berg Sinai zu Ende geredet, die beiden Tafeln des Zeugnisses, steinerne Tafeln, vom Finger Gottes beschrieben.',
    },
    32: {
        1: 'Als das Volk sah, daß Moses säumte, vom Berg herabzusteigen, rottete sich das Volk wider Aaron und sprach zu ihm: "Auf! Mach uns Götter, die vor uns herziehen! Denn also ist es mit Moses, dem Manne, der uns aus Ägypterland geführt: Wir wissen nicht, was aus ihm geworden ist."',
        2: 'Da sprach Aaron zu ihnen: "Dann reißt die goldenen Ringe ab, die in den Ohren eurer Weiber, Söhne und Töchter hängen, und bringt sie mir!"',
        3: 'Da riß sich alles Volk seine goldenen Ohrringe ab und brachte sie zu Aaron.',
        4: 'Er nahm sie aus ihrer Hand und formte sie in einer Gußform. So machte er ein Gußkalb daraus. Da sprachen sie: "Dies sind, Israel, deine Götter, die dich aus Ägypterland herausgeführt."',
        5: 'Als aber Aaron dies wahrnahm, baute er vor ihm einen Altar. Dann rief Aaron und sprach: "Morgen ist ein Fest des Herrn."',
        6: 'Da opferten sie frühmorgens Brandopfer und brachten Mahlopfer. Dann setzte sich das ganze Volk, zu essen und zu trinken. Hierauf erhob es sich zu scherzen.',
        7: 'Da sprach der Herr zu Moses: "Geh hinab! Verkehrtes tut dein Volk, das du aus Ägypterland geführt.',
        8: 'Rasch sind sie vom Pfade gewichen, den ich ihnen geboten. Sie haben sich ein Gußkalb gemacht. Dies beten sie an, opfern ihm und sprechen: \'Dies sind, Israel, deine Götter, die dich aus Ägypterland geführt.\'"',
        9: 'Und der Herr sprach zu Moses: "Ich sehe, woran ich mit diesem Volke bin. Ein widerspenstiges Volk ist es.',
        10: 'Nun laß mich, daß mein Zorn wider sie entbrenne und ich sie vernichte! Dich aber mache ich zu einem großen Volke."',
        11: 'Da begütigte Moses den Herrn, seinen Gott. "Warum willst du, Herr, so heftig deinem Volke zürnen, das du aus Ägypterland mit großer Kraft und starkem Arm geführt?',
        12: 'Warum sollen die Ägypter sagen dürfen: Zur Unheilsstunde hat er sie herausgeführt, sie in den Bergen umzubringen und von der Erde zu tilgen? Laß von deiner Zornesglut! Laß dich gereuen des Unheils über dein Volk!',
        13: 'Gedenke deiner Knechte Abraham und Isaak und Israel, was du ihnen bei dir geschworen hast! Du versprachest: \'Mehren will ich euren Stamm wie des Himmels Sterne, und dies ganze Land, von dem ich gesprochen, gebe ich eurem Stamm, daß es ihm auf ewig eigen sei.\'"',
        14: 'Da ließ sich der Herr des Unheils gereuen, das er seinem Volke zu tun gedroht.',
        15: 'So wandte sich Moses und stieg vom Berg, die zwei Tafeln des Zeugnisses in der Hand. Die Tafeln waren auf beiden Seiten beschrieben. Vorne und hinten waren sie beschrieben.',
        16: 'Die Tafeln aber waren Gotteswerk, und die Schrift Gottesschrift, gegraben auf die Tafeln.',
        17: 'Da hörte Josue den Lärm des zügellosen Volkes und sprach zu Moses: "Kriegslärm ist im Lager."',
        18: 'Er aber sprach. "Das ist kein Siegesjubel und kein Fluchgeschrei. Gemeines Schreien höre ich."',
        19: 'Als er dem Lager näherkam, sah er das Kalb und Tänze. Da loderte Mosis Zorn empor, und er warf die Tafeln weg und zerschlug sie unten am Berge.',
        20: 'Dann nahm er das Kalb, das sie gemacht, verbrannte es im Feuer und zerstieß es zu Staub. Dann streute er ihn auf das Wasser und gab ihn den Israeliten zu schlucken.',
        21: 'Dann sprach Moses zu Aaron: "Was hat dir dieses Volk getan, daß du solch schwere Schuld darüber gebracht hast?"',
        22: 'Da sprach Aaron: "Nicht zürne mein Herr! Du selber weißt, wie zügellos das Volk sein kann.',
        23: "Sie sprachen zu mir: 'Mach du uns Götter, die vor uns herziehen! Denn also ist es mit Moses, dem Manne, der uns aus Ägypterland geführt: Wir wissen nicht, was aus ihm geworden ist.'",
        24: 'Ich sprach zu ihnen: \'Wer hat Gold?\' Da rissen sie es ab und gaben es mir. Ich warf es ins Feuer. Da kam dies Kalb heraus."',
        25: 'Moses aber sah, daß das Volk ausgelassen war. Denn Aaron hatte es laufen lassen, hatte sich doch ihr Widerspruchsgeist hervorgedrängt.',
        26: 'Da trat Moses ins Lagertor und rief: "Wer für den Herrn ist, her zu mir!" Da sammelten sich bei ihm alle Levisöhne.',
        27: 'Er sprach zu ihnen: "So spricht der Herr, Israels Gott: \'Es lege jeder sein Schwert an seine Hüfte! Geht im Lager von einem Tor zum anderen und tötet, jeder selbst den eigenen Bruder, Freund und Anverwandten!\'"',
        28: 'Und die Levisöhne taten nach Mosis Wort. Vom Volke fielen an jenem Tage um 3.000 Mann.',
        29: 'Und Moses sprach: "Tut für den Herrn das Höchste, was ihr tun könnt! Denn auch bei Sohn und Bruder ist es euch möglich, ihnen heute Segen zu vermitteln."',
        30: 'Am anderen Morgen sprach Moses zu dem Volke: "Schwer habt ihr euch versündigt. Nun steige ich zum Herrn empor. Vielleicht kann ich euch Verzeihung für eure Sünde erwirken."',
        31: 'So kehrte Moses zum Herrn und sprach.- "Sieh, dieses Volk hat schwer gesündigt. Goldene Götter machte es sich.',
        32: 'Wenn du ihnen diese Sünde verzeihen wolltest! Wo nicht, so streiche mich lieber aus deinem Buche, in das du schreibst!"',
        33: 'Da sprach der Herr zu Moses: "Wer sich gegen mich versündigt, nur den streiche ich aus meinem Buche.',
        34: 'Nun aber gehe hin und führe das Volk, wohin ich dir gesagt! Fürwahr, mein Engel zieht vor dir her. Am Tage meiner Ahndung aber ahnde ich an ihnen ihre Sünde."',
        35: 'Und der Herr schlug das Volk dafür, daß sie das Kalb hatten machen lassen, das Aaron gefertigt hatte.',
    },
    33: {
        1: 'Und der Herr sprach zu Moses: "Geh, zieh hinauf von hier, du und das Volk, das du aus Ägypterland geführt, in das Land, das ich Abraham, Isaak und Jakob zugeschworen mit den Worten: \'Deinem Stamme gebe ich es!\'',
        2: 'Ich sende aber einen Engel vor dir her und vertreibe die Kanaaniter und die Amoriter, Chittiter, Periziter, Chiwiter und Jebusiter.',
        3: 'Denn in das Land, von Milch und Honig fließend, ziehe ich nicht in deiner Mitte hinauf; weil du ein widerspenstiges Volk bist. Ich müßte dich sonst unterwegs vernichten."',
        4: 'Als das Volk diese schlimme Botschaft vernahm, trauerte es, und niemand legte seinen Schmuck an.',
        5: 'Und der Herr sprach zu Moses: "Sprich zu den Söhnen Israels: \'Ihr seid ein widerspenstiges Volk. Zöge ich nur einen Augenblick in deiner Mitte mit, so müßte ich dich vertilgen. Lege keinen Schmuck mehr an, sonst wüßte ich, was ich dir täte!\'"',
        6: 'Da ließen die Israeliten vom Berge Horeb an ihren Schmuck weg.',
        7: 'Moses aber nahm das Zelt; dann schlug er es dort außerhalb des Lagers auf, entfernt vom Lager. Er nannte es Festgezelt. Wer den Herrn suchte, ging zum Festgezelt außerhalb des Lagers.',
        8: 'Sooft Moses zum Zelte hinausging, erhob sich alles Volk. Jeder stellte sich unter seine Zelttür, und so schauten sie Moses nach, bis er zum Zelte gekommen war.',
        9: 'Sooft Moses zum Zelte kam, senkte sich die Wolkensäule herab und stand an der Zelttür und redete mit Moses.',
        10: 'Sah nun das ganze Volk die Wolkensäule am Zelteingang stehen, dann begann es, jeder an seinem Zelteingang, sich niederzuwerfen.',
        11: 'Der Herr aber redete mit Moses von Angesicht zu Angesicht, wie jemand mit seinem Freunde spricht. Kehrte er ins Lager zurück, so wich sein Diener Josue, Nuns Sohn, als Lediger, nicht aus dem Zelte.',
        12: 'Moses sprach zum Herrn: "Du sagst zu mir: \'Führe dieses Volk hinauf!\' Aber du tust mir nicht kund, wen du mit mir senden willst. Und doch sagst du: \'Ich kenne dich mit Namen. In meinen Augen hast du Gnade gefunden.\'',
        13: 'Nun, habe ich in deinen Augen Gnade gefunden, dann laß mich deine Art erkennen, daß ich dich recht verstehe und mich deiner Gnade würdig zeige! Bedenke! Dein Volk ist dies Volk."',
        14: 'Er sprach: "Ginge mein Angesicht mit, beruhigte ich dich damit?"',
        15: 'Da sprach er zu ihm: "Zieht nicht dein Angesicht mit, dann führe uns nicht von hier hinauf!',
        16: 'Woran denn würde sonst erkannt, daß ich mit deinem Volk in deinen Augen Gnade gefunden, wenn nicht daran, daß Du mit uns ziehst? Dadurch sind wir ja, ich und dein Volk, vor allen Erdenvölkern ausgezeichnet."',
        17: 'Da sprach der Herr zu Moses: "Auch dies, was du erbittest, will ich tun. Du hast ja Gnade in meinen Augen gefunden. Ich kenne dich mit Namen."',
        18: 'Er sprach: "Laß mich deine Herrlichkeit schauen!"',
        19: 'Da sprach er: "Ich führe an dir vorüber all meine Herrlichkeit und nenne vor dir des Herrn Namen: Wem ich gnädig bin, dem bin ich gnädig, wem barmherzig, dem barmherzig."',
        20: 'Dann sprach er: "Mein Angesicht kannst du nicht schauen. Kein Mensch schaut mich und lebt."',
        21: 'Und der Herr sprach: "Hier bei mir ist Platz. Stell dich auf diesen Felsen!',
        22: 'Fährt meine Herrlichkeit vorüber, dann stelle ich dich in die Felsenritze und lege meine Hand auf dich, bis ich vorüber bin.',
        23: 'Ziehe ich dann meine Hand weg, dann schaust du meine Rückseite. Aber mein Angesicht bleibt unsichtbar."',
    },
    34: {
        1: 'Und der Herr sprach zu Moses: "Behaue dir zwei Steintafeln, wie die ersten! Ich schreibe dann auf die Tafeln die Worte, die auf den ersten Tafeln standen, die du zerbrochen hast.',
        2: 'Sei bereit für morgen und steige in der Frühe auf den Sinaiberg und tritt vor mich auf den Bergesgipfel!',
        3: 'Aber niemand steige mit dir hinauf! Am ganzen Berge lasse sich niemand blicken! Auch Schafe und Rinder dürfen nicht nach diesem Berg zu weiden."',
        4: 'So hieb er zwei Steintafeln wie die ersten zurecht. Und früh morgens stand Moses auf und bestieg den Berg Sinai, wie ihm der Herr befohlen, und nahm die zwei Steintafeln in seine Hand.',
        5: 'Da fuhr der Herr im Gewölke herab und stellte sich dort neben ihn; dann nannte er den Namen des Herrn.',
        6: 'Der Herr zog nämlich an ihm vorüber und rief: "Herr, Herr! Ein Gott, barmherzig und gnädig, langmütig, reich an steter Güte.',
        7: 'Tausenden wahrt er die Treue und verzeiht Schuld und Fehl und Missetat. Aber straffrei läßt er nicht, sondern ahndet der Väter Schuld an Kindern und an Enkeln, am dritten und am vierten Gliede."',
        8: 'Dann neigte sich Moses eilends zu Boden und warf sich nieder und sprach:',
        9: '"Habe ich, Herr, in deinen Augen Gnade gefunden, dann ziehe der Herr mit uns! Wohl ist es ein widerspenstiges Volk. Doch verzeihe unsere Schuld und Sünde! Mach uns zu den ewig Deinen!"',
        10: 'Und er sprach: "So schließe ich denn einen Bund: Vor all deinem Volke will ich Wunder tun, wie sie nirgends auf Erden und bei keinem Volke gewirkt worden sind. Schauen soll das ganze Volk, in dessen Mitte du weilst, wie schauervoll das Herrenwerk ist, das ich an dir tun will!',
        11: 'Merk dir, was ich dir heute gebiete! Sieh! Ich vertreibe vor dir die Amoriter, Kanaaniter, Chittiter, Periziter, Chiwiter und Jebusiter.',
        12: 'Hüte dich vor einem Bunde mit den Insassen des Landes, in das du kommst, daß er nicht zum Falle in deiner Mitte werde!',
        13: 'Ihre Altäre sollt ihr zerstören, ihre Steinmale zerbrechen, ihre heiligen Pfähle fällen!',
        14: 'Du sollst dich nicht vor einem anderen Gott niederwerfen! Der Herr heißt eifersüchtig. Ein eifersüchtiger Gott ist er.',
        15: 'Daß du keinen Bund mit des Landes Insassen schließest Wenn sie ihren Göttern nachhuren und ihren Göttern opfern und man dich einlade, iß nichts von ihren Opfern!',
        16: 'Nimm von ihren Töchtern kein Weib für deine Söhne. Ihre Töchter huren ja ihren Göttern nach, und so würden sie deine Söhne zur Götterhurerei verleiten!',
        17: 'Du sollst dir kein Göttergußbild machen!',
        18: 'Das Fest der ungesäuerten Brote halte! Sieben Tage sollst du ungesäuertes Brot essen, wie ich es dir geboten, zur Zeit des Neumonds im Abib',
        19: 'Du bist ja aus Ägypten gezogen an dem Neumond des Abib. 19 Ein jeder Erstlingswurf ist mein, und zwar ist all dein Zuchtvieh hier gemeint: der erste Wurf von Rindern und von Schafen.',
        20: 'Den ersten Wurf vom Esel sollst du mit einem Schafe auslösen! Lösest du ihn nicht aus, dann brich ihm das Genick! All deine erstgeborenen Söhne sollst du auslösen! Nicht schaue man gabenleer mein Angesicht!',
        21: 'Sechs Tage magst du arbeiten: am siebten aber sollst du ruhen! Selbst zur Zeit des Pflügens und Erntens sollst du ruhen!',
        22: 'Du sollst dir ein Wochenfest zur Zeit der Erstlinge der Weizenernte halten und dein Herbstfest an der Jahreswende!',
        23: 'Dreimal im Jahr erscheine vor dem Herrn, dem Herrn, dem Gotte Israels, alles, was bei dir ist!',
        24: 'Ich tilge viele Völker vor dir und weite dein Gebiet. Und so wird niemand dein Land begehren, solange du hinaufziehst, vor dem Herrn, deinem Gott, dreimal im Jahre zu erscheinen.',
        25: 'Du sollst meines Opfers Blut nicht mit Gesäuertem zusammen schlachten! Über Nacht soll nichts vom Passahfestopfer bis zum Morgen noch da sein!',
        26: 'Von deines Ackers Erstlingen den ersten Abhub sollst du zum Hause des Herrn, deines Gottes, bringen! Du sollst kein Böckchen in seiner Mutter Fett braten!"',
        27: 'Und der Herr sprach zu Moses: "Schreib diese Worte dir auf! Denn laut dieser Worte schließe ich mit dir und mit Israel einen Bund."',
        28: 'Und er weilte dort beim Herrn vierzig Tage und vierzig Nächte. Er aß kein Brot und trank kein Wasser. Auf die Tafeln aber schrieb er die Worte des Bundes, die zehn Worte.',
        29: 'Als Moses vom Berge Sinai niederstieg - die beiden Zeugnistafeln in Mosis Hand -, als er vom Berge niederstieg, wußte Moses nicht, daß seine Gesichtshaut von der Unterredung mit ihm strahlte.',
        30: 'Aaron und alle anderen Israeliten schauten Moses, wie seine Gesichtshaut strahlte. Da fürchteten sie sich, ihm nahe zu kommen.',
        31: 'Da rief ihnen Moses zu, und Aaron und alle Fürsten in der Gemeinschaft wandten sich ihm zu. Dann redete Moses mit ihnen.',
        32: 'Hernach traten alle Israeliten herzu, und er gebot ihnen alles, was der Herr mit ihm auf dem Berge gesprochen hatte.',
        33: 'Als Moses seine Unterredung mit ihnen beendigt hatte, legte er auf sein Antlitz einen Schleier.',
        34: 'Sooft Moses vor den Herrn kam, mit ihm zu reden, entfernte er den Schleier, bis er wieder heraustrat. Trat er heraus und meldete den Israeliten, wozu er entboten ward,',
        35: 'dann sahen die Israeliten an Mosis Antlitz, daß Mosis Gesichtshaut strahlte. Dann aber legte Moses den Schleier wieder über sein Antlitz, bis er hineinkam, mit ihm zu reden.',
    },
    35: {
        1: 'Moses versammelte nun die ganze israelitische Gemeinschaft und sprach zu ihnen: "Dies sind die Worte, die der Herr zu tun befiehlt:',
        2: "'Gearbeitet darf nur sechs Tage werden! Der siebte Tag soll euch ein heilig Ding, ein rechter Ruhetag des Herrn sein! Wer an ihm irgendeine Arbeit tut, soll getötet werden!",
        3: 'Ihr dürft in keiner eurer Siedlungen am Sabbattage Feuer machen!\'"',
        4: 'Und Moses sprach zu der ganzen israelitischen Gemeinschaft also: "Dies ist es, was der Herr befiehlt:',
        5: 'Liefert von euch aus eine Gabe für den Herrn! Wen dazu sein Herz treibt, der bringe für den Herrn eine Gabe an Gold, Silber, Kupfer,',
        6: 'an blauem und rotem Purpur, Karmesin und Linnen, Ziegenhaar,',
        7: 'gegerbten Widderfellen, Seekuhhäuten und Akazienholz,',
        8: 'Öl für den Leuchter und Spezereien zum Salböl und zum würzigen Räucherwerk',
        9: 'und Onyx- sowie andere Edelsteine zum Besatze des Schulterkleides und der Tasche!',
        10: 'Dann sollen alle, die kundigen Sinnes bei euch, kommen und alles machen, was der Herr befiehlt,',
        11: 'die Wohnung und das Zelt mit seiner Hülle und seinen Haken, Brettern, Riegeln, Säulen, Füßen,',
        12: 'die Lade, ihre Stangen, ihre Deckplatte, den verhüllenden Vorhang,',
        13: 'den Tisch mit seinen Stangen und all seinen Geräten, das Schaubrot,',
        14: 'den Leuchter zur Beleuchtung, alle seine Geräte, seine Lampen und das Leuchteröl,',
        15: 'den Rauchaltar und seine Stangen, das Salböl und das würzige Räucherwerk, den Vorhang für der Wohnung Tür,',
        16: 'den Brandopferaltar, das Kupfergitterwerk daran und seine Stangen, seine Geräte, den Kessel und sein Gestell,',
        17: 'des Vorhofs Umhänge mit seinen Säulen und Fußgestellen, des Vorhoftores Vorhang,',
        18: 'der Wohnung Pflöcke, die des Vorhofes, ihre Stricke,',
        19: 'die Schongewänder zum Dienste im Heiligtum, des Heiligtums Gewänder für den Priester Aaron und seiner Söhne Kleider für den Priesterdienst."',
        20: 'Da gingen sie, die ganze israelitische Gemeinschaft von Moses weg.',
        21: 'Dann kam jeder, den sein Sinn bewegt, und jeder, den sein Herz angetrieben; sie brachten eine Gabe dem Herrn für die Arbeit am Festgezelt, für all seinen Dienst darin und für die heiligen Gewänder.',
        22: 'Die Männer kamen neben den Weibern; alle, die ihr Herz antrieb, brachten Spangen, Ohr- und Fingerringe und Geschmeide, lauter goldene Sachen, jeder, der an Gold eine Weihegabe dem Herrn geweiht hatte.',
        23: 'Jeder, bei dem sich blauer und roter Purpur, Karmesin, Linnen, Ziegenhaar, gegerbte Widderfelle und Seekuhhäute vorgefunden, brachte es.',
        24: 'Jeder, der eine Gabe an Silber und Kupfer geben wollte, brachte diese Gabe für den Herrn, ebenso wer Akazienholz für allerlei Verwertung hatte.',
        25: 'Jedes kunstfertige Weib, das auf gewöhnliche Art spann, brachte das Gespinst, blauen und roten Purpur, Karmesin und Linnen.',
        26: 'Alle die Weiber, die ihr Sinn in Weisheit bewegt hatte, verspannen Ziegenhaar.',
        27: 'Die Fürsten brachten Onyx- und andere Edelsteine zum Besatz des Schulterkleides und der Tasche,',
        28: 'dazu die Spezereien und das Öl für den Leuchter, zum Salböl und zum wohlduftenden Räucherwerk.',
        29: 'Jeder Mann und jedes Weib brachte, was sie ihr Herz zu bringen trieb, für alle Arbeit, deren Anfertigung der Herr durch Moses geboten hatte. Die Söhne Israels brachten es freiwillig dem Herrn.',
        30: 'Moses aber sprach zu den Israeliten: "Seht! Mit Namen hat der Herr den Besalel berufen, des Uri Sohn, den Enkel Hurs, vom Stamme Juda.',
        31: 'Mit Gottesgeist erfüllte er ihn, mit Kunstsinn, Einsicht und Wissen um ein jeglich Werk,',
        32: 'und um Pläne zu ersinnen, um in Gold, Silber oder Kupfer sie auszuführen,',
        33: 'in Steinschnitt zu Füllungen und im Holzschneiden, um sie vielgestaltig auszuführen.',
        34: 'Auch die Gabe, Anregungen zu geben, hat er in sein Herz gelegt. Ihn selber und Oholiab, den Sohn Achisamaks, vom Stamme Dan,',
        35: 'sie beide hat er mit weisem Sinne erfüllt, jegliche Arbeit zu machen, die des Schmiedes und des Kunstwebers, des Buntwirkers in blauem und rotem Purpur, in Karmesin und Linnen und die des Webers. So machten sie jegliche Arbeit und ersannen Kunstwerke."',
    },
    36: {
        1: '"So mache es Besalel, Oholiab und jeder Kunstverständige, dem der Herr Weisheit und Einsicht verliehen, alle Arbeit zur Fertigung des Heiligtumes zu verstehen, Weisheit und Einsicht für alles, was der Herr befohlen hat!"',
        2: 'Hierauf berief Moses den Besalel und Oholiab und jeden kunstverständigen Mann, dem der Herr Weisheit verliehen, jeden, den sein Sinn bewegt hatte, an die Ausführung des Werkes zu gehen.',
        3: 'Sie empfingen unter Mosis Aufsicht alle Gaben, die die Israeliten für die Arbeit der Fertigstellung des Heiligtums gebracht, um sie zu verarbeiten. Aber noch brachten sie ihm jeden Morgen freiwillige Gaben.',
        4: 'Da gingen alle Weisen, die alle Arbeit am Heiligtume machten, Mann für Mann von ihrer Arbeit weg, die sie machten,',
        5: 'und sprachen zu Moses: "Das Volk bringt viel mehr, als zur Fertigung der vom Herrn gebotenen Arbeiten nötig ist."',
        6: 'Da gab Moses Befehl, und man ließ im Lager den Ruf ergehen: "Nicht Mann noch Weib mehr mache etwas zu einer Gabe für das Heiligtum!" So ward dem Volke weiteres Bringen verwehrt.',
        7: 'Stoff genug war da, um alle Arbeit auszuführen, ja übergenug.',
        8: 'So machten all die Kunstverständigen unter den am Werk Beschäftigten die Wohnung aus zehn Teppichen von gezwirntem Linnen, blauem und rotem Purpur und Karmesin. Mit Cheruben, nach Kunstwirkers Art, hatte man sie gemacht.',
        9: 'Jeder Teppich war achtundzwanzig Ellen lang und vier breit. Alle Teppiche hatten einerlei Maß.',
        10: 'Fünf Teppiche heftete man zusammen.',
        11: 'Man machte blaue Purpurschleifen am Saume des äußersten Teppichs der einen Naht, ebenso am Saum des äußersten Teppichs der anderen Naht.',
        12: 'Fünfzig Schleifen hatte man an dem einen Teppich gemacht und fünfzig am Rand des Teppichs der anderen Naht, so daß die Schleifen einander gegenüberstanden.',
        13: 'Dann machte man fünfzig goldene Haken und heftete die Teppiche mittels der Haken zusammen. So ward die Wohnung ein Ganzes.',
        14: 'Dann machte man Teppiche aus Ziegenhaar zu einem Zelt über der Wohnung. Elf Teppiche nahm man dazu.',
        15: 'jeder Teppich war dreißig Ellen lang und vier breit. Alle elf Teppiche hatten einerlei Maß.',
        16: 'Dann heftete man fünf Teppiche für sich zu einem Ganzen, ebenso die sechs Teppiche für sich.',
        17: 'Dann machte man fünfzig Schleifen am Saum des äußersten Teppichs der einen Naht und fünfzig an dem der anderen Naht.',
        18: 'Dann machte man fünfzig Kupferhaken, um das Zelt zu einem Ganzen zusammenzuheften.',
        19: 'Dann machte man eine Zeltdecke aus gegerbten Widderfellen und oben darüber eine Decke aus Seekuhhäuten.',
        20: 'Dann machte man gerade Bretter zur Wohnung aus Akazienholz.',
        21: 'Jedes Brett zehn Ellen lang und anderthalb breit,',
        22: 'an den einzelnen Brettern zwei Zapfen unter sich verbunden. So machte man alle Bretter der Wohnung.',
        23: 'Und zwar machte man an Brettern für die Wohnung zwanzig Bretter für die Südseite.',
        24: 'Unter die zwanzig Bretter machte man vierzig silberne Füße, je zwei Füße unter jedem Brett für seine zwei Zapfen.',
        25: 'Ebenso für die andere Seite der Wohnung gegen Norden zwanzig Bretter',
        26: 'mit ihren vierzig silbernen Füßen, je zwei Füße unter jedem Brett.',
        27: 'Für die Westseite machte man sechs Bretter',
        28: 'und zwei Bretter für die Winkel der Wohnung auf der Rückseite.',
        29: 'Sie waren unten doppelkantig und am Kopfende kreisrund. So machte man es mit beiden in den beiden Winkeln.',
        30: 'Somit waren es acht Bretter mit sechzehn silbernen Füßen; je zwei Füße unter jedem Brett.',
        31: 'Dann machte man fünf Akazienholzriegel für die Bretter der einen Wohnseite,',
        32: 'fünf Riegel für die Bretter der anderen Wohnseite und fünf Riegel für die Bretter der westlich gelegenen Wohnseite.',
        33: 'Den mittelsten Riegel ließ man in der Brettermitte von einem Ende zum anderen durchlaufen.',
        34: 'Die Bretter überzog man mit Gold. Aus Gold fertigte man auch die Ringe zur Aufnahme der Riegel; die Riegel überzog man gleichfalls mit Gold.',
        35: 'Dann stellte man den Vorhang her aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen, mit Cheruben in Kunstwirkerarbeit.',
        36: 'Man machte für ihn vier Akaziensäulen und überzog sie mit Gold. Auch ihre Stifte waren aus Gold, und man goß für sie vier silberne Füße.',
        37: 'Dann machte man einen Vorhang für die Zeltöffnung aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen in Buntwirkerarbeit',
        38: 'nebst seinen fünf Säulen und ihren Stiften. Ihre Köpfe und ihre Ringe überzog man mit Gold; ihre fünf Füße aber waren kupfern.',
    },
    37: {
        1: 'Und Besalel machte die Lade aus Akazienholz, zwei und eine halbe Elle lang, anderthalb breit und hoch.',
        2: 'Er überzog sie in- und auswendig mit reinem Gold und machte ihr einen goldenen Kranz ringsum.',
        3: 'Dann goß er für sie vier goldene Ringe für die vier Füße, zwei Ringe auf der einen Seite und zwei auf der anderen.',
        4: 'Dann fertigte er Akazienstangen und überzog sie mit Gold.',
        5: 'Diese Stangen zog er durch die Ringe an den beiden Seiten der Lade, um die Lade zu tragen.',
        6: 'Dann machte er aus reinem Gold eine Deckplatte, zweieinhalb Ellen lang und anderthalb breit.',
        7: 'Auch machte er zwei goldene Cherube. Er machte sie in getriebener Arbeit für die beiden Enden der Deckplatte.',
        8: 'Den einen Cherub an dem einen Ende, den anderen am anderen Ende. An beiden Enden der Deckplatte brachte er die Cherube an.',
        9: 'Die Cherube breiteten nach oben ihre Flügel, mit ihren Flügeln die Deckplatte deckend, die Gesichter sich zugekehrt. Die Cherubsgesichter aber schauten nach der Deckplatte hin.',
        10: 'Dann machte er aus Akazienholz einen Tisch, zwei Ellen lang, eine breit und anderthalb hoch.',
        11: 'Er überzog ihn mit reinem Gold und machte ihm einen goldenen Kranz ringsum.',
        12: 'Dann machte er ihm eine handbreit große Leiste ringsum, und daran machte er wieder einen goldenen Kranz ringsum.',
        13: 'Er goß für ihn vier goldene Ringe und befestigte diese Ringe an den vier Ecken seiner vier Füße.',
        14: 'Dicht an der Leiste waren die Ringe zur Aufnahme der Stangen, um den Tisch zu tragen.',
        15: 'Die Stangen machte er aus Akazienholz und überzog sie mit Gold, um den Tisch zu tragen.',
        16: 'Er machte die Geräte für den Tisch, seine Schüsseln, Schalen, Becher und Kannen zur Trankopferspende, aus reinem Gold.',
        17: 'Aus reinem Gold machte er auch den Leuchter; in getriebener Arbeit machte er den Leuchter, sein Fußgestell und seinen Schaft; seine Kelche, Knospen und Blüten gingen aus ihm hervor.',
        18: 'Von seinen Seiten gingen sechs Röhren aus, je drei auf jeder Leuchterseite.',
        19: 'An jeder Röhre waren drei Mandelblütenkelche, je eine Knospe samt der Blüte. So an allen sechs von dem Leuchter ausgehenden Röhren.',
        20: 'Am Leuchter selbst waren vier Mandelblütenkelche, mit Knospen und Blüten,',
        21: 'jedesmal eine Knospe unter jedem der drei Röhrenpaare, der sechs von ihm ausgehenden Röhren.',
        22: 'Ihre Knospen und Röhren waren aus einem Stück mit ihm, alles getriebene Arbeit aus einem Stück, von reinem Gold.',
        23: 'Dann machte er seine sieben Lampen nebst seinen Lichtscheren und Pfannen von reinem Gold.',
        24: 'Aus einem Barren Feingold machte er ihn und seine Geräte.',
        25: 'Dann machte er aus Akazienholz den Räucheraltar, eine Elle lang, eine breit, viereckig und zwei Ellen hoch. Seine Hörner gingen aus ihm hervor.',
        26: 'Er überzog mit reinem Gold ihn, seine Platte und seine Wände ringsum sowie seine Hörner und machte ihm einen goldenen Kranz ringsum.',
        27: 'Unterhalb des Kranzes machte er seinen beiden Ecken beiderseitig je zwei goldene Ringe zur Aufnahme der Stangen, um ihn daran zu tragen.',
        28: 'Die Stangen machte er aus Akazienholz und überzog sie mit Gold.',
        29: 'Dann machte er das heilige Salböl sowie das reine, wohlriechende Räucherwerk nach Salbenmischer Art.',
    },
    38: {
        1: 'Dann machte er den Brandopferaltar aus Akazienholz, fünf Ellen lang, fünf breit, viereckig und drei Ellen hoch.',
        2: 'Er machte an seinen vier Ecken seine Hörner so, daß seine Hörner an ihm ausliefen. Er überzog sie mit Kupfer.',
        3: 'Dann machte er alle Altargeräte, Töpfe, Schaufeln, Becken, Gabeln und Pfannen. Aus Kupfer machte er alle seine Geräte.',
        4: 'Für den Altar machte er ein Gitterwerk, ein kupfernes Netzwerk, unterhalb seines Gesimses bis zu seiner halben Höhe.',
        5: 'Er goß vier Ringe für die vier Ecken des Kupfergitterwerkes zur Aufnahme der Stangen.',
        6: 'Die Stangen machte er aus Akazienholz und überzog sie mit Kupfer.',
        7: 'Die Stangen zog er durch die Ringe an den Seiten des Altares, um ihn daran zu tragen.',
        8: 'Er machte ihn aus Brettern, so daß er hohl war. Das Becken machte er aus Kupfer, ebenso sein Gestell aus Kupfer von den Spiegeln der Mädchen, die den Eingang zum Festgezelt schmückten.',
        9: 'Dann machte er den Vorhof. Die Vorhofumhänge aus gezwirntem Linnen für die Südseite waren hundert Ellen lang,',
        10: 'dazu zwanzig Säulen mit ihren zwanzig Kupferfüßen. Die Säulenstifte und ihre Ringe waren silbern.',
        11: 'Für die Nordseite hundert Ellen, dazu zwanzig Säulen mit ihren zwanzig Kupferfüßen. Die Säulenstifte und ihre Ringe waren silbern.',
        12: 'Für die Westseite Umhänge von fünfzig Ellen, dazu zehn Säulen mit ihren zehn Füßen. Die Säulenstifte und ihre Ringe waren silbern.',
        13: 'Für die Ostseite fünfzig Ellen-,',
        14: 'Umhänge von fünfzehn Ellen für die eine Seite, dazu drei Säulen mit ihren drei Füßen,',
        15: 'für die andere Seite, zu beiden Seiten des Vorhoftores, Umhänge von fünfzehn Ellen, dazu drei Säulen mit ihren drei Füßen.',
        16: 'Alle Vorhofumhänge ringsum waren von gezwirntem Linnen.',
        17: 'Die Säulenfüße kupfern, die Säulenstifte und ihre Ringe silbern, ebenso der Überzug ihrer Köpfe silbern. Alle Vorhofsäulen waren mit Silberringen versehen.',
        18: 'Des Vorhoftores Vorhang war Buntwirkerarbeit aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen, zwanzig Ellen lang und fünf Ellen hoch in der Breite, entsprechend den Vorhofsumhängen.',
        19: 'Seine vier Säulen mit ihren vier Füßen waren kupfern, ihre Stifte silbern und der Überzug ihrer Köpfe und ihrer Ringe silbern.',
        20: 'Alle Pflöcke an der Wohnung und am Vorhof ringsum waren kupfern.',
        21: 'Dies sind die Verordnungen für die Wohnung, die Zeugniswohnung, wie sie auf Mosis Befehl als Dienst der Leviten unter dem Priester Itamar, dem Aaronssohn, verordnet wurden.',
        22: 'Besalel, Uris Sohn und Hurs Enkel vom Stamm Juda, machte alles, was der Herr dem Moses geboten,',
        23: 'und mit ihm Oholiab, Achisamaks Sohn, vom Stamm Dan als Schmied, Kunstwirker und Buntwirker in rotem und blauem Purpur, Karmesin und Linnen.',
        24: 'Alles Gold, das bei der Arbeit, bei aller Arbeit am Heiligtum, verwendet ward, das Gold der Spende, betrug 29 Barren und 730 Ringe nach der Währung des heiligen Ringes,',
        25: 'das Silber aus der Musterung der Gemeinde hundert Barren und 1.775 Ringe nach der Währung des heiligen Ringes,',
        26: 'je die Hälfte von jedem Kopf, ein Halbring nach der Währung des heiligen Ringes, von allen, die der Musterung von zwanzig Jahren und darüber unterlagen, 603.550 Mann.',
        27: 'Die hundert Barren Silber wurden zum Gießen der Fußgestelle des Heiligtums und der Vorhanggestelle verwendet, hundert Barren zu hundert Füßen, zu jedem Fuß ein Barren.',
        28: 'Aus den 1.775 Ringen machte man Säulenstifte, überzog ihre Köpfe und versah sie mit Ringen.',
        29: 'Das Kupfer der Weihegabe betrug 70 Barren 2.400 Ringe.',
        30: 'Daraus machte man die Füße der Tür des Bundeszeltes, den kupfernen Altar, das kupferne Gitterwerk an ihm, alle Altargeräte,',
        31: 'die Füße im Vorhof ringsum, die Füße des Vorhoftores alle Pflöcke der Wohnung und alle Pflöcke des Vorhofes ringsum.',
    },
    39: {
        1: 'Aus blauem und rotem Purpur und Karmesin machten sie die Überwürfe als Schutzdecken für das Heiligtum; ebenso die Heiligtumsgewänder für Aaron, wie der Herr dem Moses geboten hatte.',
        2: 'Das Schulterkleid machte man aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen.',
        3: 'Man schlug Goldplatten breit; dann zerschnitt man sie in Fäden, um sie in blauen und roten Purpur, Karmesin und Linnen mittels Kunstwirkerarbeit einzuarbeiten.',
        4: 'Man brachte daran Schulterstücke, unter sich verbunden, an; an beiden Enden ward es verknüpft.',
        5: 'Das Band zum Umbinden an ihm war ein Stück mit ihm von gleicher Arbeit aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen, wie der Herr dem Moses befohlen.',
        6: 'Dann richtete man Onyxsteine her, um sie mit goldenem Netzwerk einzufassen und mittels Siegelstich darin die Namen der Söhne Israels einzugraben.',
        7: 'Man setzte sie auf die Schulterstücke des Schulterkleides als Steine des Gedenkens an die Söhne Israels, wie der Herr es dem Moses befohlen hatte.',
        8: 'Die Tasche aber machte man in Kunstwirkerarbeit nach Art des Schulterkleides aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen.',
        9: 'Viereckig, gedoppelt hatte man die Tasche gemacht, je eine Spanne lang und breit, gedoppelt.',
        10: 'Man besetzte sie mit vier Reihen Edelsteinen: Karneol, Topas und Smaragd war die erste Reihe.',
        11: 'Die zweite Reihe war Rubin, Saphir und Jaspis.',
        12: 'Die dritte Hyazinth, Achat und Amethyst.',
        13: 'Die vierte Chrysolith, Onyx und Beryll; in ihrer Einfassung waren sie goldumflochten.',
        14: 'Die Steine waren nach den Namen der Söhne Israels zwölf, mittels Siegelstich jeder für einen Namen der zwölf Stämme.',
        15: 'An die Tasche machte man reingoldene Schnurkettchen.',
        16: 'Dann machte man zwei goldene Geflechte und zwei goldene Ringe. Die Ringe befestigte man an den beiden Enden der Tasche.',
        17: 'Die zwei goldenen Schnüre befestigte man an den beiden Ringen am Ende der Tasche.',
        18: 'Die zwei Enden der beiden Schnüre befestigte man an die zwei Geflechte und diese an die Schulterstücke des Schulterkleides.',
        19: 'Dann machte man zwei goldene Ringe und setzte sie an die zwei Enden der Tasche am Rand nach innen, dem Schulterkleid zu.',
        20: 'Man machte noch zwei goldene Ringe und befestigte sie an den beiden Schulterstücken des Schulterkleides unten an der Vorderseite bei der Knüpfung, doch oberhalb der Schulterkleidbinde.',
        21: 'Dann kettete man die Tasche mit ihren Ringen an die Ringe des Schulterkleides mit blauen Purpurschnüren, daß sie über der Schulterkleidsbinde blieb und sich die Tasche nicht vom Schulterkleide trennte, wie der Herr dem Moses geboten.',
        22: 'Das Oberkleid des Schulterkleides machte man in Webarbeit, ganz aus blauem Purpur.',
        23: 'Des Obergewandes Öffnung in seiner Mitte glich der eines Panzers, mit einem Saume um seine Öffnung, daß es nicht zerreiße.',
        24: 'An den Saum des Obergewandes machte man Granatäpfel aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen.',
        25: 'Aus reinem Gold machte man Glöckchen und setzte die Glöckchen zwischen die Granatäpfel hinein, rings um den Saum des Obergewandes,',
        26: 'daß immer ein Glöckchen mit einem Granatapfel abwechselte, rings um den Saum des Obergewandes, wie es der Herr dem Moses geboten hatte.',
        27: 'Die Leibröcke machte man aus Linnen in Webarbeit für Aaron und seine Söhne,',
        28: 'den Kopfbund aus Linnen, ebenso die Mützen, die Beinkleider aus gezwirntem Linnen,',
        29: 'den Gürtel aus gezwirntem Linnen, blauem und rotem Purpur und Karmesin in Buntwirkerarbeit, wie der Herr dem Moses geboten.',
        30: 'Das Blatt des heiligen Diadems machte man aus reinem Gold und schrieb darauf in Siegelstecherschrift: "Heiligtum des Herrn".',
        31: 'Man befestigte es mit einer blauen Purpurschnur oben am Kopfbund, wie der Herr dem Moses geboten.',
        32: 'So wurde alle Arbeit für die Wohnung des Festgezeltes vollendet. Die Israeliten taten ganz, wie der Herr dem Moses geboten hatte.',
        33: 'So brachten sie zu Moses die Wohnung, das Zelt und all seine Geräte, seine Haken, Bretter, Riegel, Säulen und Füße,',
        34: 'die Oberdecke aus gegerbten Widderfellen sowie die Überdecke aus Seekuhhäuten und den verhüllenden Vorhang,',
        35: 'die Zeugnislade, ihre Stangen, die Deckplatte,',
        36: 'den Tisch mit all seinen Geräten, die Schaubrote,',
        37: 'den Leuchter aus reinem Gold mit seinen Lampen, den Lampen in einer Reihe, und all seinen Geräten, sowie das Öl für den Leuchter,',
        38: 'den goldenen Altar, das Salböl, das wohlriechende Räucherwerk und den Vorhang für die Zelttür,',
        39: 'den kupfernen Altar mit dem kupfernem Gitterwerk daran, seine Stangen mit all seinen Geräten, das Becken und sein Gestell,',
        40: 'die Umhänge des Vorhofs, seine Säulen und Füße, den Vorhang für das Vorhoftor, seine Stricke und Pflöcke, sowie alle Geräte zum Dienste in der Wohnung des Bundeszeltes,',
        41: 'die Überwürfe als Schutzdecken für das Heiligtum, die Heiligtumsgewänder für den Priester Aaron und die Gewänder seiner Söhne zum Priesterdienste.',
        42: 'Wie alles der Herr dem Moses geboten, so hatten die Israeliten die gesamte Arbeit getan.',
        43: 'Da besah Moses die ganze Arbeit, und sie hatten sie so getan. So wie es der Herr befohlen, hatten sie es gemacht. Da segnete sie Moses.',
    },
    40: {
        1: 'Und der Herr sprach zu Moses:',
        2: '"Am ersten Tage des ersten Monds sollst du des Festgezeltes Wohnung aufschlagen.',
        3: 'Dann stelle die Zeugnislade darein und verhülle die Lade mit dem Vorhang!',
        4: 'Bring den Tisch hinein! Leg die Schichten (der Schaubrote) auf! Dann bringe den Leuchter hinein und setze seine Lampen auf!',
        5: 'Den goldenen Rauchaltar stelle vor die Zeugnislade und hänge den Türvorhang der Wohnung auf!',
        6: 'Und vor die Tür der Festgezeltwohnung stelle den Brandopferaltar!',
        7: 'Das Becken stelle zwischen Bundeszelt und Altar auf und gieße Wasser darein!',
        8: 'Lege ringsum den Vorhof an und hänge den Vorhang zum Vorhoftore auf!',
        9: 'Nimm Salböl! Salbe die Wohnung und alles, was darin, und weihe sie und alle ihre Geräte, daß sie ein Heiligtum werde!',
        10: 'Salbe auch den Brandopferaltar und alle seine Geräte und weihe den Altar, so daß dieser Altar hochheilig werde!',
        11: 'Salbe auch das Becken mit seinem Fußgestell und weihe es!',
        12: 'Führe Aaron mit seinen Söhnen zu des Festgezeltes Tür und wasche sie mit Wasser!',
        13: 'Bekleide Aaron mit den Kleidern für das Heiligtum! Salbe ihn und weihe ihn, daß er mir Priesterdienste tue!',
        14: 'Auch seine Söhne sollst du herbeiführen! Bekleide sie mit Leibröcken!',
        15: 'Und salbe sie, wie du ihren Vater gesalbt, daß sie uns Priesterdienste tun! Die Salbung zum ewigen Priestertum gelte für sie über ihre Geschlechter hin!"',
        16: 'Und Moses tat so. Wie ihm der Herr geboten, tat er.',
        17: 'Am ersten Tag des ersten Monats im zweiten Jahre ist die Wohnung aufgeschlagen worden.',
        18: 'Und Moses erstellte die Wohnung. Er setzte ihre Fußgestelle hin, setzte ihre Bretter darauf, fügte ihre Riegel ein und stellte ihre Säulen auf.',
        19: 'Er spannte das Zelt über die Wohnung und legte über das Zelt die Überdecke, wie der Herr dem Moses geboten.',
        20: 'Er nahm auch das Zeugnis, legte es in die Lade, steckte an die Lade die Stangen und setzte oben auf die Lade die Deckplatte.',
        21: 'Die Lade aber brachte er in die Wohnung, hängte den verhüllenden Vorhang auf und verhüllte so die Zeugnislade, wie der Herr dem Moses geboten hatte.',
        22: 'Den Tisch stellte er in das Festgezelt auf der Wohnung Nordseite außerhalb des Vorhangs.',
        23: 'Er legte darauf die Schichten der Brote vor dem Herrn zurecht, wie der Herr dem Moses geboten.',
        24: 'Den Leuchter stellte er ins Bundeszelt gegenüber dem Tisch auf die Südseite der Wohnung.',
        25: 'Er setzte die Lampen vor den Herrn, wie der Herr dem Moses gebot.',
        26: 'Den goldenen Altar stellte er ins Festgezelt vor den Vorhang',
        27: 'und zündete darauf wohlriechendes Räucherwerk an, wie der Herr dem Moses geboten.',
        28: 'Dann hängte er den Türvorhang der Wohnung auf.',
        29: 'Den Brandopferaltar aber stellte er an den Eingang des Festgezeltes; man opferte darauf das Brand- und Speiseopfer, wie der Herr dem Moses geboten hatte.',
        30: 'Das Becken aber stellte er zwischen dem Festgezelt und dem Altare auf und goß Waschwasser hinein.',
        31: 'Daraus wuschen sich Moses, Aaron und seine Söhne Hände und Füße.',
        32: 'Sooft Sie zum Festgezelt kamen und sich dem Altare nahten, wuschen sie sich, wie der Herr dem Moses geboten hatte.',
        33: 'Den Vorhof aber legte er rings um die Wohnung und den Altar an und hängte den Vorhang des Vorhoftores auf. So vollendete Moses sein Werk.',
        34: 'Da verhüllte eine Wolke das Festgezelt, hatte doch die Herrlichkeit des Herrn die Wohnung erfüllt.',
        35: 'Und Moses konnte nicht ins Festgezelt eingehen; denn die Wolke hatte sich darauf gelagert und die Herrlichkeit des Herrn die Wohnung erfüllt.',
        36: 'Wenn sich die Wolke von der Wohnung hob, zogen die Israeliten fort, auf all ihren Zügen.',
        37: 'Hob sich aber die Wolke nicht, so zogen sie nicht fort, bis sie sich hob.',
        38: 'Denn eine Wolke lag tagsüber auf der Wohnung. Des Nachts aber war Feuer darüber vor den Augen des ganzen Hauses Israel auf allen ihren Zügen.',
    },
}
